import React, { useState, useEffect, useMemo, useRef } from "react";

// ===================== 問題データ(全129問:No.343〜471) =====================
const CHAPTERS = [
  "1 生物の特徴","2 遺伝子とその働き","3 ヒトのからだの調節","4 植生と遷移","5 生態系とその保全",
  "6 進化と系統","7 細胞と分子","8 代謝","9 遺伝子発現とバイオテクノロジー","10 遺伝子の発現調節と発生",
  "11 動物の反応と行動","12 植物の成長と環境応答","13 生態と環境"
];

const QUESTIONS = [
{id:343,ch:0,lv:0,q:"すべての生物に共通する特徴を3点、下の語をすべて用いて60字程度で説明せよ。",k:["細胞","DNA","エネルギー"],s:"",a:"からだが細胞からなる。遺伝物質としてDNAをもち生殖を行う。栄養分を分解してエネルギーを取り出し活動する。(53字)",c:"細胞構造 自己増殖 代謝",e:"生物は膜で外界と隔てられた細胞からなるという構造上の特徴をもつ。細胞が分裂するときにDNAが複製・分配される。DNAは子孫に伝えられる。また、代謝を行い、代謝にはエネルギーの出入りが伴う。"},
{id:344,ch:0,lv:0,q:"原核細胞の特徴を、下の語をすべて用いて50字以内で説明せよ。",k:["核","染色体","細胞小器官"],s:"",a:"原核細胞は核をもたず、染色体は細胞質基質に存在する。また、細胞小器官をもっていない。(42字)",c:"原核細胞は核膜や細胞小器官をもたない",e:"原核細胞は、核をもたず、遺伝物質(DNA)を含む染色体は細胞質基質に存在する(核様体という)。また、細胞質基質にはミトコンドリアや色素体(葉緑体など)、ゴルジ体などの膜構造をもつ細胞小器官は存在しない。細菌などは、からだが原核細胞からなる原核生物である。一方、真核細胞は、核をもち、核内には遺伝物質(DNA)を含む染色体が存在する。また、細胞質基質中にはさまざまな細胞小器官が存在する。"},
{id:345,ch:0,lv:0,q:"動物細胞と植物細胞の細胞構造の相違点を、次の語をすべて用いて50字以内で述べよ。",k:["葉緑体","細胞壁","液胞"],s:"",a:"植物細胞は葉緑体や細胞壁をもつが動物細胞はもたない。動物細胞は、植物細胞ほど液胞が発達しない。(47字)",c:"動物細胞は葉緑体や細胞壁、発達した液胞をもたない",e:"多くの植物細胞は光合成を行う葉緑体と、植物体を支える細胞壁をもつ。動物細胞は光合成を行わず、細胞壁をもたない。また、液胞は動物細胞にも存在するがあまり発達せず、光学顕微鏡ではふつう観察されない。"},
{id:346,ch:0,lv:0,q:"代謝とは何か。下の語をすべて用いて100字程度で説明せよ。",k:["同化","異化","エネルギー"],s:"",a:"代謝とは、生物体内で行われる化学反応を指す。単純な物質から複雑な物質を合成し、エネルギーの吸収を伴う過程の同化と、複雑な物質を単純な物質に分解し、エネルギーの放出を伴う過程の異化に大別される。(96字)",c:"同化はエネルギーの吸収、異化はエネルギーの放出を伴う",e:"生物は外部からエネルギーを取り入れて生活している。生命活動には物質の合成・分解が常に伴い、これら化学反応全体を代謝という。このうち、単純な物質から複雑な物質を合成し、エネルギーの吸収を伴う過程を同化、複雑な物質を単純な物質に分解し、エネルギーの放出を伴う過程を異化という。光合成は同化、呼吸は異化の代表的な反応である。"},
{id:347,ch:0,lv:0,q:"ATPとはどのような物質か、その構造と機能を、下の語をすべて用いて100字以内で説明せよ。",k:["アデニン","リボース","リン酸","高エネルギーリン酸結合"],s:"",a:"アデニンとリボースが結合したアデノシンに、リン酸が3分子結合した化合物で、リン酸どうしの結合である高エネルギーリン酸結合が切れるときにエネルギーが放出され、代謝におけるエネルギーの出入りを仲介する。(99字)",c:"アデノシン三リン酸、エネルギーの出入りを仲介",e:"ATPは、塩基の一種であるアデニンと糖の一種であるリボースが結合したアデノシンに、3分子のリン酸が結合した化合物である。ATP内のリン酸どうしの結合は高エネルギーリン酸結合と呼ばれ、切れるときにエネルギーが放出される。ATPの末端のリン酸が切り離されると、ADP(アデノシン二リン酸)とリン酸が生じる。ADPとリン酸からATPが合成されるときには、エネルギーが吸収される。ATPはすべての生物の体内に存在し、代謝におけるエネルギーの仲立ちをしていることから、生体内でのエネルギー通貨とも呼ばれる。"},
{id:348,ch:0,lv:0,q:"酵素の特徴を、下の語をすべて用いて50字以内で説明せよ。",k:["基質特異性","くり返し作用"],s:"",a:"酵素は触媒としてくり返し作用し、代謝を円滑に進める。また、特定の物質にのみ作用する基質特異性をもつ。(50字)",c:"触媒 特定の物質にのみ反応",e:"触媒は、自身は変化せず化学反応を促進する物質である。酵素は生物がつくる触媒であり、自身は変化しないためくり返し作用する。酵素が作用する物質を基質といい、反応の結果生じる物質を生成物という。酵素の本体はタンパク質であり、その立体構造から特定の基質にのみ作用する基質特異性をもつ。"},
{id:349,ch:0,lv:1,q:"ウイルスは「遺伝情報をもつ」という生物に共通する特徴をもっているが、通常、生物とはみなされていない。その理由を60字以内で述べよ。",k:[],s:"岡山大改題",a:"細胞構造をもたず、自ら増殖することもできない。さらに、代謝を行わないなど、生物の特徴の一部しかもたない存在だから。(57字)",c:"生物に共通の特徴:細胞・生殖・代謝",e:"ウイルスは、遺伝物質(DNAまたはRNA)とタンパク質でできた微小粒子で細胞構造をもたない。さらに、代謝を行わないことや、自己増殖はできず、侵入した細胞内の物質やしくみを利用しなければ増殖できないことなど、生物としての特徴をすべて備えていないことから、無生物とされている。"},
{id:350,ch:0,lv:1,q:"核の構造と働きについて60字以内で説明せよ。",k:[],s:"",a:"核の最外層は核膜となっており、内部に染色体が存在する。核は、細胞の形態や機能を決める重要な働きをもつ。(51字)",c:"核膜 染色体",e:"真核細胞には、ふつう1個の核が含まれる。核の最外層は、二重膜でできた核膜となっており、核膜には核膜孔という細胞質基質との間で物質の輸送を行う小孔が存在する。内部には遺伝情報を保持するDNAを含む染色体、RNAを含む核小体が存在する。細胞の形態や機能は主に核が保持する遺伝情報によって決定される。"},
{id:351,ch:0,lv:1,q:"生物は、一見すると多様であるが、共通した特徴がみられる。この理由を、多様な脊椎動物における共通の特徴を例にして120字以内で述べよ。",k:[],s:"",a:"脊椎動物は、魚類・両生類・ハ虫類・鳥類・哺乳類と多様なグループに分かれているが、すべて脊椎をもつという共通の性質がある。この共通性は、脊椎動物の共通祖先が無脊椎動物と分岐した際にもっていた性質を受け継いでいるためであると考えられる。(116字)",c:"共通性は共通の祖先に由来",e:"脊椎動物には、魚類、両生類、ハ虫類、哺乳類などのグループがあるが、これらはすべて脊椎をもつという共通性がある。これは、それぞれのグループが個別に獲得したものではなく、脊椎動物が無脊椎動物から分岐した時点で存在していた共通の祖先がもっていた特徴を受け継いだためであると考えられる。一方、四肢や、生涯を通じての肺呼吸、胎生というふえ方などの特徴は、もっているグループもあれば、もっていないグループもある。これらの特徴は進化の過程を通じて、生活する環境に適応してきた結果であると考えられる。"},
{id:352,ch:0,lv:1,q:"代謝におけるエネルギーの出入りとATPの関係について、以下の語句をすべて用いて170字以内で説明せよ。",k:["光合成","呼吸","タンパク質の合成","筋収縮"],s:"",a:"光合成では、光エネルギーがATPの化学エネルギーに変換され、ATPの分解により放出されるエネルギーを用いて有機物が合成される。一方、呼吸では、有機物の分解によって放出されたエネルギーを用いてATPが合成される。呼吸で合成されたATPは、タンパク質の合成などの化学反応や、筋収縮のエネルギーなど、さまざまな生命活動にエネルギーを供給する。(168字)",c:"ATPは代謝におけるエネルギーの出入りを仲介",e:"ATPは、生体におけるエネルギー通貨とも呼ばれ、代謝におけるエネルギーの出入りを仲介している。光合成では、まず、葉緑体が光エネルギーを吸収してATPがつくられる。このATPのエネルギーを用いて、二酸化炭素を材料にして有機物が合成される。合成された有機物には、光エネルギーに由来するエネルギーが化学エネルギーに変換されて貯蔵されていることになる。呼吸は、酸素を用いて有機物を分解することで、有機物に蓄えられていた化学エネルギーをATPの化学エネルギーに変換する過程である。呼吸によって産生されたATPを利用して、生体物質の合成や、筋収縮(運動エネルギーへの変換)などのさまざまな生命活動が営まれる。"},
{id:353,ch:0,lv:1,q:"光学顕微鏡において、レンズを取り付ける順序とピントの合わせ方における注意点について、それぞれ70字以内で説明せよ。",k:[],s:"",a:"〔レンズを取り付ける順序〕鏡筒内にゴミやほこりが入って対物レンズが汚れないようにするため、先に接眼レンズを取り付け、その後、対物レンズを取り付ける。(61字)\n〔ピントの合わせ方〕対物レンズとプレパラートの接触を避けるため、まず、対物レンズとプレパラートを近づけておき、この2つを離すように動かしてピントを合わせる。(68字)",c:"取り付けは接眼レンズから。ピント合わせは対物レンズとプレパラートを離しながら",e:"顕微鏡のレンズが傷ついたり、汚れたりすると正確な観察ができなくなる。顕微鏡の鏡筒は空洞であるため、接眼レンズを先に取り付け、上から落ちてくるゴミで対物レンズを汚さないようにする。レンズの取り外しは、対物レンズから行う。ピントを調節する場合は、プレパラートと対物レンズの接触によって、対物レンズに傷や汚れがつかないように注意する。まず、横から見ながら対物レンズとプレパラートを近づけた後、接眼レンズをのぞいて、調節ねじを回してステージを下げ、対物レンズからプレパラートを遠ざけながら行う。"},
{id:354,ch:1,lv:0,q:"光学顕微鏡下において、間期の細胞と分裂期の細胞とはどのように区別できるか。次の語をすべて用いて70字以内で説明せよ。",k:["間期","分裂期","糸状","棒状"],s:"19. 宮城大",a:"間期の細胞では染色体が糸状にほどけて核内に広がっているが、分裂期の細胞では染色体が凝縮して棒状となっていることで区別できる。(62字)",c:"染色体は分裂期に凝縮する",e:"間期にはDNAの複製や分裂の準備が行われ、分裂期には複製したDNAを含む染色体を2つの娘細胞に等しく分配する。間期には、染色体は糸状になって核内に分散しているが、分裂期には凝縮して棒状となる。"},
{id:355,ch:1,lv:0,q:"タマネギの根端のような体細胞分裂を盛んに行っている組織を観察すると、一般的に、分裂している細胞と分裂していない細胞が混在している。これらの細胞の数の比から、どのようなことがわかるか、次の語をすべて用いて50字以内で答えよ。",k:["比率","細胞周期"],s:"鹿児島大",a:"細胞の数の比率は細胞周期での各時期の長さの比率と一致することから、間期と分裂期の長さの比率がわかる。(50字)",c:"間期と分裂期の長さの比率",e:"分裂を盛んに行っている細胞集団において、観察される各時期の細胞数の比は、細胞周期に占める各時期の時間の比と等しくなる。すなわち、観察される細胞数が多いと、その時期に要する時間は長いと考えられる。たとえば、観察された細胞のなかで間期の細胞が最も多かったとき、その細胞周期に占める間期の時間が最も長いと判断できる。"},
{id:356,ch:1,lv:0,q:"遺伝情報がタンパク質へ翻訳されるまでの一連の過程を、次の語をすべて用いて80字以内で説明せよ。",k:["RNA","転写","アミノ酸"],s:"",a:"まず、DNAの遺伝情報が転写され、RNAが合成される。次に、RNAの塩基3つの配列が1つのアミノ酸を指定し、これが次々につなげられてタンパク質がつくられる。(78字)",c:"DNA→RNA→タンパク質。塩基3つの配列が1つのアミノ酸を指定",e:"タンパク質合成の過程:遺伝情報の転写ではDNAの遺伝情報が転写され、RNAが合成される。遺伝情報の伝達ではmRNAは核膜孔を通り、核外に出る。遺伝情報の翻訳ではmRNAの塩基3つの配列(コドン)にしたがってアミノ酸どうしが並んで結合し、タンパク質が合成される。"},
{id:357,ch:1,lv:0,q:"翻訳の過程において、終止コドンの一つ前のコドンに対応するアミノ酸まででポリペプチド鎖の伸長が止まるのはなぜか。次の語をすべて用いて50字以内で説明せよ。",k:["tRNA","アミノ酸","終止コドン"],s:"18. 秋田大",a:"終止コドンに対応するアンチコドンをもつtRNAが存在せず、対応するアミノ酸がないため。(43字)",c:"終止コドン tRNA アンチコドン",e:"mRNAのコドンには64種類があり、そのうち3つ(UAA・UAG・UGA)はアミノ酸を指定せず、翻訳の終了を示す終止コドンである。この3つのコドンがアミノ酸を指定しないのは、これらのコドンに対応したアンチコドンをもつtRNAが存在しないためである。その他のコドンには、それぞれ対応するアンチコドンをもつtRNAが存在し、翻訳の際には特定のアミノ酸と結合してmRNAへ運び、mRNAのコドンにもとづいてアミノ酸が並べられ、特定のアミノ酸配列をもつタンパク質が合成される。"},
{id:358,ch:1,lv:0,q:"ヒトの体細胞に含まれる遺伝情報は基本的にすべて同一である。その理由を、次の語をすべて用いて90字以内で説明せよ。",k:["受精卵","体細胞分裂","娘細胞"],s:"",a:"体細胞分裂では、1個の母細胞から同じ遺伝情報をもつ2個の娘細胞がつくられる。ヒトの体細胞は、1個の受精卵が体細胞分裂をくり返して生じるため、基本的にすべて同じ遺伝情報をもつ。(87字)",c:"体細胞分裂におけるDNAの複製と分配",e:"多細胞生物の体細胞は、1個の受精卵が体細胞分裂をくり返して生じたものである。したがって、体細胞がもつ遺伝情報は、すべて基本的に同一のものとなる。からだを構成する細胞にはさまざまな働きをもつものが存在するが、それらはすべて同一の遺伝情報をもち、発現する遺伝子がそれぞれ異なることで機能や形態を変化させている。一方、すべての細胞の生存に不可欠な遺伝子は、どの細胞でも常に発現している。このような遺伝子は、ハウスキーピング遺伝子と呼ばれる。"},
{id:359,ch:1,lv:1,q:"ワトソンとクリックは、1953年にDNAの構造モデルに関する論文を発表した。この論文のなかで彼らは、「特定の塩基で対が形成されるという構造は、遺伝物質の複製機構について暗示するものである」と述べている。DNAの構造と遺伝物質の複製機構がどのように関係するかを、次の語をすべて用いて130字以内で説明せよ。",k:["相補的","ヌクレオチド鎖","塩基配列","鋳型鎖"],s:"18. 北九州市立大改題",a:"DNAの構造は、2本のヌクレオチド鎖の塩基どうしが相補的に結合した二重らせん構造である。DNAの複製では、この相補的な結合が解け、それぞれのヌクレオチド鎖が鋳型鎖となり、相補的な塩基配列のヌクレオチド鎖が新たに合成され、同一の2本鎖DNAが2本できる。(126字)",c:"塩基の相補性 半保存的複製",e:"ワトソンとクリックの発表したDNAの二重らせん構造のモデルは、2本のヌクレオチド鎖が互いに相補的な塩基どうしで結合し、全体がねじれたらせん状の構造をとるというものであった。これはDNAの構造を明らかにすると同時に、DNAが複製される際には、このような塩基の相補性にもとづいて新しいヌクレオチド鎖が合成されている可能性を示唆するものでもあった。"},
{id:360,ch:1,lv:1,q:"DNAとRNAを比較すると、前者の方が細胞内で安定であり、後者の方が不安定である。遺伝情報の保持と形質の発現におけるそれぞれの機能を考えたとき、RNAが不安定であってもかまわない理由を、50字以内で答えよ。",k:[],s:"徳島大改題",a:"RNAは遺伝情報の保持には関与せず、形質発現の際に形成され、発現が終了すると分解されてしまうため。(49字)",c:"遺伝情報の保持 形質発現",e:"DNAは、二重らせん構造をしており、安定な構造をもつ物質である。これは遺伝情報を保持する役割をもつDNAにとって重要な性質である。一方、RNAは、DNAほど安定でなく分解されやすい性質をもつ。これは、遺伝情報の発現という一時的な処理に用いられているRNAにとって重要な性質であると考えられる。"},
{id:361,ch:1,lv:1,q:"遺伝情報が翻訳される過程では、mRNAの3個の塩基が1個のアミノ酸を指定している。もし、mRNAの2個の塩基が1個のアミノ酸を指定していた場合、どのような不都合が生じるか。120字以内で説明せよ。",k:[],s:"19. 岩手大",a:"遺伝情報はmRNAの4種類の塩基で20種類のアミノ酸を指定している。mRNAの2個の塩基が1個のアミノ酸を指定していた場合、指定できるアミノ酸の種類は4×4=16通りとなり、20種類すべてのアミノ酸を指定することができない。(112字)",c:"コドンの種類数とアミノ酸の種類数",e:"タンパク質を構成するアミノ酸は20種類ある。mRNAが1塩基で1つのアミノ酸を指定すると4種類のアミノ酸が、2塩基でアミノ酸を指定すると4×4=16種類のアミノ酸が指定できるが、いずれの場合も20種類あるアミノ酸すべてを指定できない。したがって、mRNAのコドンは少なくとも3塩基である必要がある。"},
{id:362,ch:2,lv:0,q:"自律神経系の働きについて、次の語をすべて用いて100字以内で述べよ。",k:["支配","意思","交感神経","作用"],s:"",a:"自律神経系は、間脳の視床下部などによって支配されており、意思とは無関係に働く。交感神経と副交感神経があり、同じ器官に分布していることが多く、きっ抗的に作用して器官の働きを調節する。(90字)",c:"間脳の視床下部 意思とは無関係 交感神経 副交感神経 きっ抗的",e:"自律神経系の働きについて問われているので、働きに関して簡潔に解答する。活動時や緊張した状態では交感神経の働きが優位になり、安静な状態では副交感神経の働きが優位になる。また、交感神経は脊髄から出て各器官に伸びており、副交感神経は中脳や延髄、脊髄の下端から出て各器官に伸びている。"},
{id:363,ch:2,lv:0,q:"ホルモンとはどのようなものか、次の語をすべて用いて100字以内で説明せよ。",k:["内分泌腺","体液","標的器官","受容体"],s:"",a:"ホルモンは、内分泌腺から血液中に放出され、体液の循環によって全身に運ばれて微量で作用し、決まった反応を起こさせる。標的器官の細胞にしかそのホルモンの受容体が存在しないため、特定の細胞のみに作用する。(99字)",c:"体液による全身への運搬 標的器官 微量で作用",e:"ホルモンは、タンパク質または脂質の一種であるステロイドなどを主成分とする物質である。標的器官には、特定のホルモンを受容する標的細胞がある。ホルモンは、標的細胞の受容体に結合して作用を引き起こす。ホルモンは血流によって運ばれるため、ホルモンによる調節作用は反応が起こるまでに時間がかかり、自律神経系に比べゆっくりと持続的に働く。"},
{id:364,ch:2,lv:0,q:"外気温が低い場合でも、体温を維持する機構がヒトには備わっている。特に、自律神経によって体温を上昇させる機構について、放散、発熱量の語を用い、自律神経の作用する具体的な器官や臓器をあげて、60字以内で述べよ。",k:["放散","発熱量"],s:"熊本県立大改題",a:"体表の血管を収縮させて熱の放散を減らし、心臓の拍動促進や副腎髄質からのアドレナリン分泌を促進して発熱量をふやす。(56字)",c:"熱の放散の減少 アドレナリン 発熱量の増加",e:"交感神経による調節のほか、脳下垂体前葉から甲状腺刺激ホルモンや副腎皮質刺激ホルモンが分泌され、甲状腺からはチロキシンが、副腎皮質からは糖質コルチコイドが分泌される。これらの働きで、肝臓や筋肉などで代謝が促進され、発熱量が増加する。"},
{id:365,ch:2,lv:0,q:"「抗原」「抗体」「B細胞」「食作用」の語を用いて、体液性免疫とはどのようなしくみであるかを100字以内で説明せよ。",k:["抗原","抗体","B細胞","食作用"],s:"",a:"抗原が体内に侵入すると、B細胞が抗体産生細胞に分化して抗体を産生し、体液中に分泌する。抗体は、抗原と特異的に結合して、抗原の病原性を失わせたり、マクロファージなどの食作用を促進したりする。(94字)",c:"B細胞が抗体を体液中に分泌 抗原は抗体と特異的に結合",e:"抗原となる非自己物質が体内に侵入すると、樹状細胞やマクロファージに取り込まれる。樹状細胞から抗原の情報を受け取ったヘルパーT細胞は増殖してB細胞を活性化する。活性化されて増殖したB細胞は抗体産生細胞に分化して抗体を産生する。抗体は抗原と結合して抗原抗体複合体をつくり、抗原抗体複合体はマクロファージなどの食作用によって排除される。B細胞の一部は免疫記憶細胞として残るため、同じ抗原が2度目に侵入した際には、急速に多量の抗体がつくられる。"},
{id:366,ch:2,lv:0,q:"病原体やその毒素に対する免疫を高めることを目的とする医療として、予防接種と血清療法が知られている。両者の違いについて、次の語をすべて用いて100字以内で述べよ。",k:["抗体","病原体","即効性","遅効性"],s:"",a:"予防接種は、無毒化・弱毒化した病原体などによって抗体をつくらせる方法で、遅効性だが継続的である。血清療法は、他の動物につくらせた抗体を含む血清を注射して治療を行う方法で、即効性があるが一時的である。(99字)",c:"予防接種は抗原を与えて抗体をつくらせ、血清療法は直接抗体を投与する",e:"ワクチンを抗原として用いて免疫記憶細胞をつくらせ、病原体への感染を予防する方法を予防接種といい、結核に対するもの(BCG)や、インフルエンザなどの多くの伝染病に対するものがつくられている。血清療法では、ウマなどの動物に抗原を接種して抗体をつくらせ、その血清を治療に使用する。ジフテリアや腸チフスのほか、マムシの毒素による中毒症などの場合に用いる。"},
{id:367,ch:2,lv:1,q:"摂食によって血糖濃度は急激に増加する。自律神経系とホルモンの共同作業による血糖濃度低下のしくみについて、160字以内で説明せよ。",k:[],s:"信州大改題",a:"間脳の視床下部にある血糖濃度調節の中枢が、血糖濃度の上昇を感知し、副交感神経を介してすい臓のランゲルハンス島のB細胞を刺激したり、B細胞自体が血糖濃度の上昇を感知したりしてインスリンの分泌が促進される。インスリンは、グルコースの細胞での吸収や分解、肝臓でのグリコーゲンへの合成を促進し、血糖濃度を低下させる。(154字)",c:"間脳の視床下部で感知 すい臓ランゲルハンス島のB細胞",e:"低血糖のときには、副腎髄質から分泌されるアドレナリンやすい臓のランゲルハンス島のA細胞からのグルカゴンがグリコーゲンの分解を促進させる。また、副腎皮質から分泌される糖質コルチコイドは、タンパク質からのグルコース合成を促進させる。これらの働きによって、血糖濃度を高めている。"},
{id:368,ch:2,lv:1,q:"血液凝固のしくみを、血小板、血しょう、凝固因子、フィブリン、血球のすべての語を用いて160字以内で説明せよ。",k:["血小板","血しょう","凝固因子","フィブリン","血球"],s:"19. 早稲田大改題",a:"血小板から放出される凝固因子や、血しょう中にある別の凝固因子とカルシウムイオンの働きによって、血しょう中のプロトロンビンがトロンビンに変化する。トロンビンはフィブリノーゲンを繊維状のタンパク質であるフィブリンに変え、これが赤血球などの血球と絡み合って血ぺいをつくり、血液を凝固させる。(142字)",c:"凝固因子 カルシウムイオン トロンビン フィブリン 血ぺい",e:"血液凝固を防止する方法には、①血液にクエン酸ナトリウムを加えてカルシウムイオンを除く。②血液にヘパリンを加えてトロンビンの生成を阻害する。③低温に保って、血液凝固に関与する酵素活性を低下させる。などがある。"},
{id:369,ch:2,lv:1,q:"細胞内に侵入したウイルスは抗体の作用を受けにくいが、その理由を50字以内で述べよ。",k:[],s:"",a:"体液性免疫を担う抗体は、分子量が大きく、細胞内に進入できないので、細胞内のウイルスには作用できない。(50字)",c:"抗体は細胞内に入らない",e:"抗体は体液中に存在し、細胞内には入らない。ウイルスに感染した細胞は、キラーT細胞やNK細胞が直接攻撃して排除する。"},
{id:370,ch:2,lv:1,q:"免疫応答が過剰に働くと、どのような不都合が起こるか。花粉症を例にあげて80字以内で説明せよ。",k:[],s:"浜松医大改題",a:"花粉を抗原としてできた抗体がマスト細胞に付着する。再び同じ花粉が侵入すると抗原抗体反応が起こり、マスト細胞からヒスタミンが分泌されくしゃみなどが起こる。(76字)",c:"マスト細胞 抗原抗体反応 ヒスタミン",e:"ある抗原に対する免疫が、正常とは異なり過敏に反応する現象をアレルギーと呼ぶ。即時型過敏症(体液性免疫による)と遅延型過敏症(細胞性免疫による)とがある。ヒスタミンが血管や神経の細胞に結合すると、アレルギー症状が現れるが、抗ヒスタミン剤を投与してヒスタミンの受容体をふさぐと発症しない。マスト細胞は肥満細胞ともいい、B細胞から放出される特定の抗体(IgE)と結合する。この抗体に抗原が結合すると、マスト細胞からヒスタミンなどの物質が放出される。"},
{id:371,ch:2,lv:1,q:"毎年、異なったインフルエンザウイルス株を用いたワクチンが接種されているのはなぜか。その理由をウイルスの遺伝情報と関連付けて80字以内で答えよ。",k:[],s:"東北大改題",a:"インフルエンザウイルスの遺伝子は突然変異が起こりやすく、抗体が作用するウイルス表面のタンパク質に変化が生じやすい。このため、毎年流行する型が異なるため。(76字)",c:"ウイルスの遺伝子に突然変異が起こりやすい タンパク質の変化",e:"インフルエンザウイルスは、1本鎖RNAを遺伝物質とするウイルスである。1本鎖RNAは、2本鎖DNAに比べて不安定な物質であり、突然変異が起こりやすい。このため、インフルエンザウイルスの表面にあるタンパク質は、抗原性を毎年わずかに変化させてヒトの免疫機構から逃れ、流行し続ける。インフルエンザに対する抗体は、インフルエンザワクチン接種後1〜2週間でつくられる。抗体の量は、接種の2週間後にピークに達し、ワクチン接種後、2〜3カ月すると抗体の量はしだいに下がりはじめ、免疫の力も落ちてくる。"},
{id:372,ch:2,lv:1,q:"ヒトの免疫力を低下させる病気の例にエイズ(後天性免疫不全症候群)がある。HIV(ヒト免疫不全ウイルス)感染により生じるエイズは日和見感染症を伴うが、この理由を句読点を含めて60字以上80字以内で説明せよ。",k:[],s:"20. 鳥取大",a:"HIVがヘルパーT細胞に感染しこれを破壊すると、B細胞やキラーT細胞が活性化されなくなり、マクロファージやNK細胞の活性化もできなくなるから。(71字)",c:"ヘルパーT細胞の破壊",e:"エイズは、HIVと呼ばれるウイルスの感染によって免疫機能が損なわれる病気である。HIVは免疫機能の中心的な存在であるヘルパーT細胞内に侵入し、これを破壊する。これによって獲得免疫の機能が正常に働かなくなり、各種の病原体が急速に増殖してさまざまな感染症やがんなどを発症しやすくなる。エイズ患者などの免疫力の低下したヒトでみられる、健康なヒトには感染を起こさないような感染力の弱い病原体が原因で発症する感染症は、日和見感染症と呼ばれる。"},
{id:373,ch:3,lv:0,q:"発達した森林における階層による光環境の違いについて、次の語をすべて用いて50字以内で説明せよ。",k:["光","階層","林冠","林床"],s:"",a:"光のほとんどは林冠で吸収されるため、階層が下になるほど暗くなり、林床に届く光はごくわずかである。(48字)",c:"林冠で光の多くは吸収される",e:"発達した森林は、高木層・亜高木層・低木層・草本層などに分けることができ、これを階層構造という。林冠でほとんどの光が吸収され、階層が下になるほど暗くなる。"},
{id:374,ch:3,lv:0,q:"光合成速度は二酸化炭素の消費速度だが、植物に十分な光を照射して二酸化炭素の吸収速度を調べても直接光合成速度は測れない。どのようにして光合成速度を求めればよいか。次の語をすべて用いて60字以内で答えよ。",k:["吸収","放出","呼吸"],s:"",a:"同じ温度条件下において、光照射時の二酸化炭素吸収速度と、暗黒下での二酸化炭素放出速度である呼吸速度を足して求める。(57字)",c:"光照射時の二酸化炭素吸収速度 暗黒下での呼吸速度",e:"植物は、光合成を行って二酸化炭素を消費しているとき、同時に呼吸も行って二酸化炭素を生成している。暗黒下では光合成が行われず呼吸のみが行われており、二酸化炭素の放出量から呼吸速度を求めることができる。したがって、光合成速度は、光照射時の二酸化炭素吸収量(見かけの光合成量)に呼吸量を足して求めることができる。ただし、光合成速度と呼吸速度は温度の影響を受けるため、温度条件をそろえることが必要となる。"},
{id:375,ch:3,lv:0,q:"先駆種とは、どのような種のことをいうのか、次の語をすべて用いてその特徴を50字以内で述べよ。",k:["遷移","土壌"],s:"",a:"遷移の初期段階に進入する植物で、土壌がほとんどなく、乾燥した裸地でも生育できるという特徴をもつ。(48字)",c:"遷移の初期段階に進入する植物",e:"暖温帯における遷移の一般的なモデルでは、裸地にコケ植物や地衣類が進入するが、裸地の状態によっては種子植物が先駆種となることがある。これらの植物には、種子や果実が風などによって運ばれやすい、陽生植物で乾燥に強いなどの特徴がみられる。また、オオバヤシャブシやミヤマハンノキなどの木本類も先駆種となることがある。これらは根に窒素固定細菌を共生させており、栄養分の乏しい場所でも生育することができる。"},
{id:376,ch:3,lv:0,q:"植生の一次遷移には乾性遷移と湿性遷移がある。乾性遷移と湿性遷移との違いについて、次の語をすべて用いて50字以内で答えよ。",k:["裸地","水"],s:"",a:"乾性遷移は溶岩などの陸上の裸地からはじまるが、湿性遷移は湖沼などの水がたまった場所からはじまる。(48字)",c:"乾性遷移は陸上ではじまる遷移。湿性遷移は湖沼からはじまる遷移",e:"乾性遷移は、陸上でみられる一次遷移である。湿性遷移は、湖沼などからはじまる一次遷移である。湖沼はやがて湿原、草原となり、その後の遷移は乾性遷移と同じ過程を経て進行する。"},
{id:377,ch:3,lv:0,q:"陸上のバイオームの種類と分布を決める要因について、次の語をすべて用いて60字以内で説明せよ。",k:["植物","生育"],s:"",a:"陸上のバイオームは植生の違いで区分され、各地域に生育する植物は、年平均気温と年降水量によって決まる。(50字)",c:"年平均気温 年降水量",e:"陸上では、植物が生産者となり、また、植物はさまざまな動物のすみかとなる。このため、陸上のバイオームはそこに生育する植物に依存して成立し、また、その植物全体の相観によって区別される。それぞれの地域に生育する植物は、気候による影響を受け、気候を決定する主な要因には気温と降水量がある。"},
{id:378,ch:3,lv:0,q:"日本のバイオームの成立と分布の特徴について、次の語をすべて用いて90字以内で説明せよ。",k:["年平均気温","年降水量"],s:"",a:"森林が成立するのに十分な量の年降水量があるため、主に緯度の差による年平均気温の違いによって、針葉樹林、夏緑樹林、照葉樹林、亜熱帯多雨林の4つの異なるバイオームが分布する。(85字)",c:"年平均気温の違いによる4つの森林のバイオーム",e:"日本の水平分布に関する記述問題である。解答に示したように、日本では降水量が十分であるため気温がバイオームの決定要因になっている。"},
{id:379,ch:3,lv:1,q:"陽生植物と陰生植物をそれぞれ、両者の光補償点の中間の強さの光で育てたとき、植物の生育はどのようになると考えられるか。その理由を含めて、110字以内で説明せよ。",k:[],s:"九州大改題",a:"陽生植物では、光の強さが光補償点に達しておらず、呼吸量が光合成量を上回るので、体内の有機物が減少し、やがて枯れる。陰生植物は、光補償点より強い光が当たるため、光合成量が呼吸量を上回り、有機物が蓄積されて成長する。(105字)",c:"光補償点 光合成速度 呼吸速度",e:"陽生植物は光補償点と光飽和点が高いのに対して、陰生植物は光補償点と光飽和点が低い。ふつう、陽生植物と陰生植物では、陽生植物の方が光補償点が高い。したがって、両植物の光補償点の中間の光の強さでは、陰生植物は光補償点を超えているが、陽生植物では光補償点を超えていない状態となる。このため、陰生植物は生育できるが、陽生植物は生育できない。"},
{id:380,ch:3,lv:1,q:"陽樹を含めた陽生植物が遷移初期で優占し、極相林の暗い林床では生育できない理由を100字以内で説明せよ。",k:[],s:"18. 岐阜大改題",a:"陽生植物は、光飽和点が高く強光下で盛んに光合成を行うので、遷移初期にはより早く成長し優占する。また、暗い林床では、光の強さが光補償点を下回り、呼吸速度が光合成速度より大きくなるので生育できない。(97字)",c:"陽生植物は光飽和点と光補償点がともに高い。陰生植物は光飽和点と光補償点がともに低い",e:"陽生植物は、光飽和点が高いという特性が、遷移初期において生存競争上有利に働く。陰生植物は、光補償点が低いという特性が、遷移後期において生存競争上有利に働く。"},
{id:381,ch:3,lv:1,q:"同一植物の葉でも、遮光のない条件下で生じた陽葉と遮光条件下で生じた陰葉がある。この2種類の葉はどのように異なるか100字以内で説明せよ。",k:[],s:"常盤大改題",a:"陽葉は光補償点や光飽和点が高く、暗い環境では呼吸速度が大きく不利だが明るい環境では高い生産力を示す。陰葉は光補償点や光飽和点が低く、生産力は低いが薄暗い環境でも呼吸を上回る光合成を行える。(96字)",c:"陽葉:光補償点や光飽和点が高い。陰葉:光補償点や光飽和点が低い",e:"成木では、1本の木の葉でも生える位置により明るい場所もあれば暗い場所もある。明るい場所には陽葉が、暗い場所には陰葉がつくられる。陽樹の葉を陽葉、陰樹の葉を陰葉というのではない。2つのタイプの葉をもつことが、からだ全体で生産性を高めることにつながっている。なお、両者を比べると、陽葉の方が陰葉よりも小さく、葉肉が発達しており厚みがあることが多い。"},
{id:382,ch:3,lv:1,q:"遷移は大きく一次遷移と二次遷移に分けられる。それらの遷移の特徴を100字以内で説明せよ。",k:[],s:"20. 東京農工大改題",a:"一次遷移は土壌が未形成な裸地からはじまる。二次遷移は山火事や伐採の跡地などからはじまるもので、既存の土壌中に栄養塩類や植物の根や種子なども含まれている。そのため、遷移の速度は一次遷移に比べて大きい。(99字)",c:"一次遷移は裸地からはじまる 二次遷移は土壌が存在する",e:"一次遷移は火山活動などによって生じた裸地からはじまる。二次遷移では土壌形成が完了しており、土壌中の栄養塩類も十分にある場合が多い。"},
{id:383,ch:3,lv:1,q:"日本の森林バイオームのうち、東北地方に分布するものと九州に分布するものでは樹木の落葉性に違いがある。その違いは分布域の気候にどのような点で有利だと考えられるか150字以内で説明せよ。",k:[],s:"愛知教育大",a:"東北地方の冬は低温で日射量も少ないため、光合成で得られる利益より葉を維持するコストが大きくなる。そのため、低温の環境では秋に落葉することが有利だといえる。一方、九州は比較的温暖で日射量も多いため、冬でも光合成の利益を見込める。よって、温暖な環境では、一年を通して葉をつけておくことが有利だといえる。(149字)",c:"冬は低温で日射量が少ない:落葉樹(夏緑樹林)。冬でも温暖で日射量が多い:常緑樹(照葉樹林)",e:"東北地方は夏緑樹林、九州は照葉樹林である。この問題では、両者の形態の違いではなく、気候に応じた落葉性の違いを述べることがポイントになる。冬季に得られる利益と不利益のバランスに着目するとよい。なお、常緑樹も落葉しないわけではなく、多くのものは春になり新しい葉が出るころに古い葉を落とす。"},
{id:384,ch:4,lv:0,q:"食物網とは何か、次の語をすべて用いて60字以内で説明せよ。",k:["被食者","捕食者","食物連鎖"],s:"",a:"被食者と捕食者の間にみられる食物連鎖のつながりが、直線的なつながりではなく複雑な網目状になった関係のこと。(53字)",c:"複雑な網目状",e:"草本→バッタ→カエル→ヘビのように、直線的な捕食-被食の関係を食物連鎖というが、実際の生態系ではヘビはカエルのみを捕食するわけではない。多様な種の捕食-被食の関係を示していくと複雑な網目状となる。"},
{id:385,ch:4,lv:0,q:"富栄養化によってプランクトンが多量に増殖すると、水生生物の大量死につながる。このしくみを、次の語をすべて用いて60字以内で説明せよ。",k:["死骸","分解","酸素"],s:"",a:"増殖したプランクトンの死骸が分解される際、水中の酸素が消費され水生生物が十分な酸素を得ることができなくなるため。(57字)",c:"死骸の分解による水中の酸素の消費",e:"分解者も生産者がつくり出した有機物に依存するということから、消費者の一部である。ここでいう有機物は増殖したプランクトンの死骸であり、これらを分解するときに、水中の酸素が大量に消費される。これも、赤潮やアオコによる水界の生態系への悪影響の1つであり、水生生物の大量死につながる。"},
{id:386,ch:4,lv:0,q:"水田には多様な生物が生息しているが耕作が放棄されると、それまで生息していた生物が減少する可能性がある。その理由を、水をためることに関連させて50字以内で説明せよ。",k:[],s:"20. 弘前大改題",a:"水田に水をためなくなることで、生活や産卵に水を必要とする生物が生息できなくなるため。(42字)",c:"環境の多様性が失われることによって、生物の多様性が失われる",e:"水田は、人の手によって定期的に水がためられることで、トンボやカエルなどの繁殖場所となったり、タガメやゲンゴロウなどの生育場所となったりする。多様な環境が、多様な生物の生息を可能とする一例である。"},
{id:387,ch:4,lv:0,q:"森林に生息する動物にとって生息地が開発などによって分断化されると、その個体数の減少につながる可能性がある。その理由を「繁殖相手」という語を用いて80字以内で説明せよ。",k:["繁殖相手"],s:"",a:"分断化により行動範囲が制限されるようになると、個体どうしが出会う機会が減少する。その結果、繁殖相手を見つけにくくなり、子孫を残せなくなるため。(71字)",c:"行動の制限 個体どうしの出会いの機会の減少",e:"分断化による影響は、繁殖相手を見つけにくくなるだけでなく、すみかとなる場所や水や食物を得る場所など、生活に欠かせない場所にたどり着けなくなるといった問題もある。本問では「繁殖相手」という語句を用いるよう指定されているが、特に指定がなければ、水や食物などの資源に言及してもよい。一見すると自然豊かにみえる環境であったとしても、道路やダムの建設による生息地の分断化が、生息する生物の個体数減少につながっている場合がある。現在、日本では、道路やダムなどの開発を行う際には、それが環境に及ぼす影響を事前に調査、予測、評価し、環境への適正な配慮がなされるようにする環境アセスメントの実施が義務づけられている。"},
{id:388,ch:4,lv:0,q:"メチル水銀などの物質が生物体内に蓄積する理由を次の語をすべて用いて40字以内で説明せよ。",k:["分解","排出"],s:"20. 京都産業大改題",a:"体内で分解されにくく、脂肪に溶け込みやすく排出されにくい物質であるため。(36字)",c:"分解されにくい 排出されにくい",e:"ここで問われていることは、「生物体内」に蓄積する理由であり、「高次の消費者により高濃度」に蓄積する理由ではない。そのため、「食物連鎖により高濃度に蓄積される」という内容に触れる必要はない。また、字数制限が40字よりも少ない場合は、「脂肪に溶け込みやすい」という内容は省略して構わない。「生物濃縮」は「有害物質をため込む」ということではない。あくまで環境中には微量にしか含まれない物質が、生体内に蓄積されることを指す。たとえば、DHA(ドコサヘキサエン酸)という脂肪酸は、海産の微生物がつくったものが、食物連鎖を通じて魚類に蓄積される。特に、マグロなどの大型魚には高濃度に蓄積される。"},
{id:389,ch:4,lv:1,q:"河川の自然浄化に関連して、汚水流入直後から河川の溶存酸素量が低下し、その後汚濁物質の減少にしたがって上昇した。これらの理由について、微生物と関連付けて回復の段階を追いながら、100字程度で説明せよ。",k:[],s:"18. 群馬大改題",a:"汚水中の有機物を細菌が分解する際に酸素が消費され溶存酸素量は低下する。有機物の分解に伴って栄養塩類が生じ、これを吸収して藻類が増殖する。増殖した藻類の光合成によって酸素が供給され溶存酸素量が上昇する。(100字)",c:"有機物の分解による酸素の消費 藻類の光合成による酸素の増加",e:"細菌などが酸素を用いてタンパク質を分解すると、NH₄⁺などが生じる。これを栄養塩類として藻類が吸収して増殖する。"},
{id:390,ch:4,lv:1,q:"干潟には、富栄養化した海水を浄化する機能があるとされる。干潟で、生物によって海水の浄化が起こるしくみを、60字以内で説明せよ。",k:[],s:"20. 日本女子大",a:"生産者である藻類は海水中の栄養塩類を利用し増殖する。これを消費者が摂食し、最終的に干潟の外に移動させることで浄化される。(60字)",c:"生産者が栄養塩類を取り込む。高次消費者が干潟から移動する",e:"アサリなどの貝類のろ過作用により水質が浄化されることもあるが、最終的には栄養塩類を取り込んだ生物が高次の消費者に捕食されることで干潟の生態系から栄養塩類が取り除かれる。たとえば、大型の回遊魚が捕食し、沖合で老廃物を排出することなどが考えられる。さらに、干潟は遠浅であるため干満差により海底が露出し、海鳥による魚介類の捕食も進みやすい。干潟は水質浄化のほか、生物多様性の維持、レクリエーションの場の提供などさまざまな生態系サービスを与える。"},
{id:391,ch:4,lv:1,q:"温室効果とはどのような作用か、60字以内で説明せよ。",k:[],s:"20. 宮城大改題",a:"地表から放出される熱エネルギーを大気中の二酸化炭素などが吸収し、再び放出することで、地表や大気の温度を上昇させる作用。(59字)",c:"二酸化炭素やメタンが熱エネルギーを吸収",e:"温室効果とは決してネガティブなものではなく、全くなくなってしまうと地球の平均気温は30℃ほど低下してしまうといわれている。本問では温室効果の作用のみを問われているので、ネガティブな要素は説明する必要はない。なお、温室効果で最も影響が大きいのは水蒸気であるが、これは人間活動の影響で増加するものではないので通常、説明では触れない。"},
{id:392,ch:4,lv:1,q:"外来生物は在来種の捕食など生態系にさまざまな問題を引き起こしているが、外来生物の多くは原産地では大きな影響を及ぼしていない。その理由として考えられることを60字以内で説明せよ。",k:[],s:"20. 三重大",a:"原産地では天敵となる捕食者がいたり、同じ資源をめぐって競争関係にある生物が存在したりすることで過度に増殖しないため。(58字)",c:"天敵の存在が増殖を抑制している",e:"マメのなかまで、つる植物のクズは、緑化や土壌の流出防止、飼料としての利用を目的として、日本からアメリカに導入された。しかし、移入先の環境で増殖し、ほかの植物の成長を妨げ、問題となっている。イギリスではイタドリが同様の問題を引き起こしている。このように日本では問題になっていない生物が、国外の生態系で悪影響を及ぼしている例もみられる。なお、解答の「資源」には、空間や光なども含まれる。"},
{id:393,ch:4,lv:1,q:"外来生物の例として、日本の生態系において生物多様性の喪失につながり、対応策がすでに講じられている脊椎動物種の事例を1つ挙げ、動物種名、それが生態系に対して及ぼしている影響および実際の対応策について120字程度で説明せよ。",k:[],s:"18. 岩手大",a:"フイリマングースは、ハブの駆除を目的として沖縄や奄美大島に持ち込まれたが、在来種であるアマミノクロウサギなどを捕食しその個体数を減少させた。そのため、フイリマングースの個体数を減少させるためにワナを用いて捕獲する事業が進められている。(117字)",c:"外来生物の生態系への影響",e:"「生物多様性の喪失につながり、対応策がすでに講じられている脊椎動物」という指定があるため、解答の範囲は意外と狭い。解答しやすいものとして、フイリマングースやオオクチバスの例があげられる。オオクチバスの場合は、琵琶湖で実施されている「外来魚回収ボックス」など具体的な対応策をあげるとよい。他にもアライグマやハリネズミ、カミツキガメなどペットとして飼育されていたものが野生化した例もあげられる。人間生活に対する被害ではなく、生態系への影響を記述することに注意する。"},
{id:394,ch:5,lv:0,q:"化学進化について、次の語をすべて用いて65字以内で説明せよ。",k:["生物の誕生","無機物","有機物"],s:"",a:"生物の誕生以前に起こった、無機物から簡単な有機物ができて、さらにそれらから生物を構成する複雑な有機物が生成されるまでの過程。(62字)",c:"生物の進化の前段階 無機物から分子量の小さい有機物、分子量の小さい有機物から分子量の大きい有機物",e:"始原生物が誕生する前に、無機物から分子量の小さい有機物が合成され、次に、これらの有機物から分子量の大きい有機物が合成され、生物を構成する有機物が生じたと考えられている。この過程を化学進化という。化学進化が起きた場としては、熱水噴出孔のような環境が考えられている。なお、分子量の小さい有機物に関しては、隕石によって宇宙から飛来したものもあるとする考え方もあり、小惑星探査機「はやぶさ」「はやぶさ2」を用いたプロジェクトでは、生命を構成する有機物の由来の調査も実施されている。"},
{id:395,ch:5,lv:0,q:"遺伝的浮動について、次の語をすべて用いて35字以内で説明せよ。",k:["世代","遺伝子頻度"],s:"",a:"次の世代に伝えられる遺伝子頻度が、偶然によって変動する現象。(30字)",c:"偶然による変動",e:"個体の生存や繁殖に有利にも不利にも働かない遺伝子の場合、自然選択が働かない。このような場合でも次の世代に受け継がれる遺伝子は無作為に選ばれるので、遺伝子頻度は偶然に左右されて変化する。その影響は、集団が小さいほど強くなる。特に、自然災害や移出などによる、小集団化によって起こる遺伝子頻度の変化をびん首効果という。"},
{id:396,ch:5,lv:0,q:"DNAの塩基配列やタンパク質のアミノ酸配列のデータをもとにした分子系統樹が、形質をもとにした系統樹よりも優れている点を、次の語をすべて用いて55字以内で説明せよ。",k:["分岐年代","分子時計","2つの種"],s:"",a:"分子に生じる変化は一定の速度で起こるという分子時計の考え方から、2つの種の分岐年代の推定が容易にできる。(52字)",c:"分子に生じる変化は一定の速度 分岐年代の推定",e:"DNAの塩基配列の突然変異やタンパク質のアミノ酸配列の変化は、一定の確率で蓄積していく。このような、分子に生じる変化の一定性は分子時計と呼ばれる。2つの種に共通する分子内の変化量を比較することで、共通祖先から分岐した年代を推定することができる。なお、使用する語の指示がなければ、他にも次のような利点があげられる。・類縁関係が遠く、形態等がまったく異なる種間でも比較が可能である。・研究者による考え方の違いが現れず、客観的な比較が可能である。"},
{id:397,ch:5,lv:0,q:"ウーズが提唱した3ドメイン説とはどのような考え方か、次の語をすべて用いて60字以内で説明せよ。",k:["rRNA","グループ","界","ドメイン","分類階級"],s:"",a:"rRNAの塩基配列にもとづいて生物を3つのグループに分け、それらをドメインと呼んで界よりも上位の分類階級とする考え方。(58字)",c:"rRNAの塩基配列の解析 界よりも上位の分類階級",e:"ウーズは、界よりも上位の分類階級としてドメインを設けることを提唱し、生物全体を、細菌(バクテリア)、アーキア(古細菌)、真核生物(ユーカリア)の3つのグループに分けた。1977年、ウーズは、rRNAの塩基配列の解析結果から、原核生物をメタン菌・高度好塩菌などが属するアーキアと、大腸菌・シアノバクテリアなどが属する細菌に区分した。その後、RNAポリメラーゼの構造やタンパク質の遺伝子の解析結果などから、アーキアは細菌よりも真核生物に近縁であることが示された。"},
{id:398,ch:5,lv:0,q:"旧口動物と新口動物の発生様式の違いを、次の語をすべて用いて50字以内で答えよ。",k:["胚発生","原口"],s:"",a:"旧口動物は、胚発生時に出現する原口が口になり、新口動物は、原口とは別の部分に新しく口ができる。(47字)",c:"旧口動物…原口が口になる。新口動物…原口とは別の部分に口ができる",e:"動物は、発生初期の胚にみられる細胞層である胚葉の分化の程度によって、分化がみられない側生動物、外・内の2つの胚葉がみられる二胚葉動物、外・中・内の3つの胚葉がみられる三胚葉動物に大きく分けられる。そのなかの三胚葉動物には、胚発生時に出現する原口が成体の口になる旧口動物と、原口とは別の部分に口ができる新口動物とがある。新口動物の定義として、一般的に「原口が肛門になる」といわれることもあるが、原口が閉じて別の場所に肛門ができるというような例外もあるため避けた方が無難である。"},
{id:399,ch:5,lv:1,q:"有性生殖を行う生物が配偶子をつくり出す際に行う減数分裂は、生物に遺伝的な多様性をもたらす重要なプロセスでもある。遺伝的多様性を生み出すための配偶子形成時の2つのしくみとはどのようなものか、100字以内で説明せよ。",k:[],s:"21. 三重大改題",a:"相同染色体が別々の配偶子に分配されることによって、遺伝子の組み合わせの異なる配偶子が生じるしくみと、連鎖している遺伝子の組換えが起こることによって、遺伝子の組み合わせがさらに多様になるしくみ。(96字)",c:"相同染色体の組み合わせ 連鎖している遺伝子の組換え",e:"2組の相同染色体にある3つの遺伝子にだけ着目したモデルで考える。配偶子は減数分裂を経てつくられ、単に相同染色体が分配されるだけであれば、その組み合わせによって、4種類の配偶子がつくられることになる。しかし、減数分裂の際には乗換えが起こって、連鎖している遺伝子が組換えられることもあるため、2組の相同染色体にある3つの遺伝子に着目しただけでも8種類の配偶子ができることになる。染色体の数や、遺伝子の数が多くなるほど、配偶子の種類は膨大になる。配偶子の遺伝子構成が多様であればあるほど、配偶子の合体によって生じる新個体の多様性は大きくなる。"},
{id:400,ch:5,lv:1,q:"新しい機能をもった遺伝子が誕生する過程において、遺伝子重複が重要な役割を果たしてきたと考えられている。遺伝子重複のあとに、新しい機能をもった遺伝子が誕生するしくみを100字以内で説明せよ。",k:[],s:"お茶の水女子大",a:"遺伝子重複が起きると、一方の遺伝子で本来の形質が発現していれば、他方に突然変異が生じても生存に影響を及ぼさない場合があり、その結果、突然変異が起こった遺伝子から新しい機能が生じることがある。(95字)",c:"一方の遺伝子によって本来の形質が発現。他方が変異しても生存に影響を及ぼさない",e:"遺伝子重複は、ゲノムの倍数化や染色体の乗換えの異常などによって生じる。突然変異の多くは、遺伝子の働きを失わせ、生存に不利に働いて集団中に残らない。しかし、遺伝子重複が生じた場合、一方に突然変異が生じても生存に不利にならない場合があり、その結果、突然変異が起きた遺伝子から新しい機能をもった遺伝子が生じる場合がある。このような例としては、水晶体に含まれるタンパク質であるクリスタリンの遺伝子や、視覚に関わるタンパク質であるオプシンの遺伝子、Hox遺伝子群などが有名である。"},
{id:401,ch:5,lv:1,q:"突然変異でDNAの塩基配列が変化しても、タンパク質のアミノ酸配列は変化しないことがある。それはどのようなときか、50字以内で説明せよ。",k:[],s:"21. 大分大",a:"コドンが異なっていても同じアミノ酸を指定する場合があり、DNAの塩基配列の変化がこれに相当したとき。(50字)",c:"コドンが異なっていても同じアミノ酸を指定する場合がある",e:"mRNAのヌクレオチドの塩基には、A・G・C・Uの4種類が用いられている。アミノ酸を指定するmRNAの塩基3つの並び(トリプレット)をコドンと呼ぶ。コドンは、塩基4種類に対して3つの組み合わせでできているため、4³=64通り存在する。これに対して、タンパク質に用いられているアミノ酸の種類は20種類あるので、同じアミノ酸を指定するコドンが複数ある場合がある。たとえば、GCU、GCC、GCA、GCGは、いずれもアラニンを指定する。これらのコドンでは、3番目の塩基で置換が起こってもアラニンを指定する。"},
{id:402,ch:5,lv:1,q:"種は、生物の分類の基本となる単位である。生物学で最も一般的に使用される種の定義を、70字以内で説明せよ。",k:[],s:"21. 大阪医科薬科大改題",a:"形態や性質が基本的に同じで、他個体と交配したときに生殖能力をもつ子を生み出すことができ、他の生物群とは生殖的に隔離されている生物群。(66字)",c:"形態や性質が同じ 生殖能力のある子を生み出す 生殖的に隔離されている",e:"種の概念は大変難しく、専門家の間でも完全に同意を得られるような種の定義は存在していない。特に、原核生物である細菌には、有性生殖が確認されていないもの、プラスミドの交換を通して類縁関係が遠くても遺伝情報の交換ができるもの、外見は同じでも遺伝的に極めて多様性に富むものなどがあり、より一層難しくなる。そのようななかで、有性生殖を行う真核生物、特に動物を中心に考えると、①形態や性質が共通している、②自由な交配によって、生殖能力をもつ子を残すことができる、③他の生物群と生殖的に隔離されている、という定義が一般的になる。しかし、このように定義しても、セグロカモメがアメリカセグロカモメと雑種を形成するように、生殖的隔離によって種を明確に区別するのが難しい例もある。"},
{id:403,ch:5,lv:1,q:"植物の主要な生物群(コケ植物・シダ植物・裸子植物・被子植物)はどのように進化してきたか、次の語をすべて用いて125字以内で説明せよ。",k:["子房","種子","胞子","維管束","胚珠"],s:"21. 熊本大",a:"まず、共通の祖先から、維管束が未発達のままのコケ植物と維管束が発達したシダ植物に分岐した。次に、胞子による生殖を行うシダ植物から、種子を形成する種子植物が生じ、この種子植物が、胚珠が裸出している裸子植物と胚珠が子房の中にある被子植物とに分岐した。(123字)",c:"維管束が発達していないか発達しているか 胞子でふえるか種子でふえるか 胚珠が裸出しているか子房に覆われているか",e:"植物は、陸上の環境に適応し、光合成を行う多細胞生物で、コケ植物、シダ植物、種子植物にわけられる。コケ植物とシダ植物は胞子でふえる。また、シダ植物と種子植物は維管束が発達しており、種子植物は、種子を形成してふえる。さらに種子植物は、子房の有無によって、裸子植物と被子植物にわけられる。"},
{id:404,ch:6,lv:0,q:"生命活動における水がもつ主な役割を、次の語をすべて用いて40字以内で答えよ。",k:["溶媒","比熱"],s:"",a:"さまざまな物質を溶かす溶媒となる。また、比熱が大きいため、温度を保持する。(37字)",c:"物質の運搬 化学反応 温度変化",e:"水は、さまざまな物質を溶かすことができ、細胞内での化学反応の場となったり、体内での物質の運搬を仲立ちする役割を担ったりしている。また、比熱が大きく温度変化に多くの熱を必要とするため、細胞の温度を保つのに役立っている。"},
{id:405,ch:6,lv:0,q:"能動輸送と受動輸送の違いについて、次の語をすべて用いて60字以内で答えよ。",k:["拡散","ATP","濃度勾配"],s:"",a:"受動輸送は濃度勾配に従った拡散による物質輸送で、能動輸送はATPを消費して濃度勾配に逆らう物質輸送である。(53字)",c:"受動輸送 能動輸送 エネルギー",e:"膜を挟んだ内外の濃度勾配に従って、物質が移動する現象を受動輸送といい、エネルギーを必要としない。輸送タンパク質を介さないものと、介するものがある。膜を挟んだ内外の濃度勾配に逆らって、物質が移動する現象を能動輸送といい、ATPや他の溶質の濃度勾配などのエネルギーを必要とする。輸送タンパク質を介して行われる。"},
{id:406,ch:6,lv:0,q:"脂質二重層とはどのような構造か、次の語をすべて用いて60字以内で説明せよ。",k:["リン脂質","疎水性","親水性"],s:"",a:"リン脂質分子には、疎水性と親水性の部分があり、疎水性の部分を内側に、親水性の部分を外側に向け2層に並んでいる。(55字)",c:"脂質二重層 リン脂質 疎水性部分 親水性部分",e:"生体膜の主成分であるリン脂質は、1分子のグリセリンに2分子の脂肪酸と1分子のリン酸が結合してできている。分子中には、水をはじく性質(疎水性)の部分と水になじみやすい性質(親水性)の部分をもつ。"},
{id:407,ch:6,lv:0,q:"高温になるとタンパク質は、酵素としての働きを失う。なぜタンパク質は高温になると酵素としての働きを失うのか、次の語をすべて用いて20字以内で説明せよ。",k:["熱","立体構造"],s:"21. 三重大改題",a:"熱によって立体構造が変化するため。(17字)",c:"変性 立体構造 失活",e:"タンパク質は、熱によって水素結合などが切れ、立体構造が変化する。立体構造が変化して、タンパク質の性質が変化する現象を変性という。変性は、強い酸やアルカリによっても起こる。また、酵素が働きを失うことは失活と呼ばれる。"},
{id:408,ch:6,lv:0,q:"酵素に基質特異性がみられる理由を、次の語をすべて用いて60字以内で答えよ。",k:["活性部位","立体構造"],s:"",a:"酵素の種類によって、活性部位の立体構造は決まっており、この構造に適合する物質のみが酵素と結合し反応するため。(54字)",c:"活性部位 立体構造 基質特異性",e:"酵素分子内には、基質分子と結合して触媒作用を示す活性部位と呼ばれるそれぞれの酵素に特有な構造をした部位がある。鍵と鍵穴の関係のように活性部位にぴったりと適合する基質のみが酵素と結合し、酵素-基質複合体を形成する。"},
{id:409,ch:6,lv:1,q:"動物細胞では、水に次いで多い構成物質はタンパク質であるが、植物細胞では、水に次いで多い構成物質は何か。理由とともに50字以内で答えよ。",k:[],s:"21. 福井県立大",a:"植物細胞は細胞壁をもち、その主成分は炭水化物のセルロースであるため、炭水化物の割合が高い。(45字)",c:"細胞壁の主成分はセルロース",e:"細胞を構成する基本的な物質は、タンパク質・炭水化物・脂質・核酸などの有機物や水などの無機物である。そのうち、水が最も多くの質量を占めている。"},
{id:410,ch:6,lv:1,q:"細胞膜のリン脂質二重層に対する通過のしやすさがホルモンによって異なる理由を、リン脂質二重層とホルモンの物質としての性質にもとづいて65字以内で説明せよ。",k:[],s:"21. 大阪医科薬科大改題",a:"リン脂質二重層は内部に疎水性の領域があるため、脂溶性が高いホルモンは細胞膜を透過するが、水溶性が高いホルモンは透過できない。(62字)",c:"親水性(水溶性) 疎水性(脂溶性)",e:"ホルモンが標的細胞の受容体に結合するとき、タンパク質からなるホルモンは、細胞表面の受容体と結合する。一方、ステロイドからなるホルモンは、細胞膜を透過して細胞内の受容体と結合する。"},
{id:411,ch:6,lv:1,q:"リボソームで合成されたタンパク質が、小胞体からゴルジ体へどのように運ばれるかを100字以内で答えよ。",k:[],s:"21. 立教大改題",a:"粗面小胞体上のリボソームで合成されたタンパク質は、粗面小胞体の膜を通過して、内部に取り込まれる。取り込まれたタンパク質は、小胞体の内部を移動し、小胞体から小胞を介してゴルジ体へと運ばれる。(94字)",c:"粗面小胞体 リボソーム 小胞 ゴルジ体",e:"小胞体は、一重の膜からなる袋状、または管状の構造をしており、これがつながりあって細胞質基質に広がっている。小胞体には、表面にリボソームが付着した粗面小胞体と、リボソームが付着していない滑面小胞体がある。リボソームで合成されたタンパク質の多くは、小胞体の内部を移動して小胞体から分離した小胞に包まれてゴルジ体に運ばれる。"},
{id:412,ch:6,lv:1,q:"酵素におけるアロステリック効果とはどのようなものか80字以内で答えよ。",k:[],s:"21. 東京医科歯科大改題",a:"アロステリック部位をもつ酵素でみられ、この部分に調節物質が結合すると酵素の立体構造が可逆的に変化して基質との親和性が変化し、反応速度が調節される現象。(75字)",c:"アロステリック部位 調節物質 反応速度の変化",e:"酵素のフィードバック調節にはアロステリック酵素が関わっていることが多い。アロステリック酵素は、活性部位を複数もち、基質濃度に対する反応速度の変化を表すグラフがS字になる。"},
{id:413,ch:6,lv:1,q:"一定量の酵素に対して基質の濃度をしだいに増していくと、基質濃度がある濃度に達するまでは反応速度は上昇するが、それ以上では反応速度が一定になる。反応速度が一定になる理由を80字以内で答えよ。",k:[],s:"21. 前橋工科大改題",a:"基質濃度が十分高くなるとすべての酵素が基質と結合し、個々の酵素は反応を終えて生成物が活性部位から離れるまで、次の基質と結合できないため。(68字)",c:"(基質濃度が低いとき)基質と結合していない酵素がある。(基質濃度が高いとき)すべての酵素が基質と結合する",e:"酵素濃度が一定のときは、基質濃度が低いと反応速度は基質濃度に比例して大きくなる。基質濃度が十分に高いときはすべての酵素が基質と結合し、酵素の活性部位に結合した基質が反応して離れるまでは、次の基質が結合できないため反応速度は一定になる。このときの反応速度を最大反応速度という。"},
{id:414,ch:7,lv:0,q:"植物の葉は、クロロフィルがあるため緑色に見える。緑色に見える理由を、クロロフィルの性質にもとづき、次の語をすべて用いて60字以内で説明せよ。",k:["青紫色光","赤色光","緑色光","反射"],s:"",a:"クロロフィルは赤色光と青紫色光をよく吸収するが、緑色光はほとんど吸収されずに反射されてヒトの眼に届くため。(53字)",c:"赤色光と青紫色光は吸収 緑色光は吸収されず反射・透過・散乱",e:"太陽から放射される電磁波のうち、その波長の違いをヒトが色の違いとして感知できるものを可視光線と呼ぶ。可視光線は、その波長の違いによって、赤色〜紫色へと連続的に変化するように見える。植物のもつ光合成色素の一種であるクロロフィルは、これらの可視光線のうち青紫色と赤色の光をよく吸収するが、緑色の光はほとんど吸収しない。そのため、太陽光が葉に当たると、吸収されなかった緑色の光は葉で反射、もしくは透過、散乱する。葉で反射や透過、散乱した緑色の光がヒトの眼に届くため、葉は表から見ても透かして見ても緑色に見える。"},
{id:415,ch:7,lv:0,q:"クロロフィルaは、赤色の光(波長680nm付近)と青色〜青紫色の光(430nm付近)を強く吸収し、500nm付近の光はほとんど吸収しない。しかし、500nm付近の光も光合成には有効である。その理由を、次の語をすべて用いて30字程度で答えよ。",k:["カロテン","光合成色素","吸収"],s:"名古屋大改題",a:"500nm付近の光も吸収するカロテンなどの光合成色素をもつため。(30字)",c:"カロテンなどによる吸収",e:"光合成色素には、クロロフィルa以外にクロロフィルbやカロテンなどがあり、各色素で吸収できる光の波長が異なっている。βカロテンは、クロロフィルaがほとんど吸収しない500nm付近の光を吸収することができる。"},
{id:416,ch:7,lv:0,q:"カルビン回路は光に依存しない反応であるが、多くの植物では昼間に働く。その理由を、次の語をすべて用いて60字程度で説明せよ。",k:["ATP","NADPH","光"],s:"慶応大改題",a:"カルビン回路で使用されるATPやNADPHは、光がない状態では生成されないので、夜間はこれらが欠乏して反応が進まないため。(58字)",c:"ATPとNADPHの生成には光が必要",e:"光合成の過程において、光化学系、電子伝達系、ATP合成酵素は、チラコイドに存在する。光化学系は光を必要とする反応であり、光が照射されない状態では、ATP、NADPH+H⁺はつくられない。一方、ストロマに存在するカルビン回路は、光に依存しない反応ではあるが、チラコイドで生成されたATPとNADPHを利用して二酸化炭素の固定を行う。したがって、これらが欠乏した状態では、カルビン回路も進行しなくなる。"},
{id:417,ch:7,lv:0,q:"酸素の供給を止めると、電子伝達系に引き続き、クエン酸回路も停止する。その理由を、次の語をすべて用いて140字以内で述べよ。",k:["NADH","FADH₂","NAD⁺","FAD"],s:"",a:"酸素は電子伝達系の最終段階で消費されるため、酸素の供給を止めると電子伝達系が停止する。電子伝達系が停止することによって、NADHやFADH₂がH⁺とe⁻を放出してNAD⁺やFADに戻ることができなくなる。その結果、クエン酸回路での脱水素反応も進行しなくなり、クエン酸回路も停止するため。(136字)",c:"NAD⁺やFADに戻ることができない",e:"呼吸の過程は、解糖系、クエン酸回路、電子伝達系の3段階に分けられる。呼吸で消費される酸素は、解糖系とクエン酸回路で生じたNADHやFADH₂などから放出されるH⁺やe⁻と電子伝達系の最終段階で反応し、水を生じる。酸素の供給がなくなると、解糖系とクエン酸回路で生じたNADHやFADH₂などのH⁺やe⁻が電子伝達系において放出されなくなり、NADHやFADH₂は、NAD⁺やFADに戻ることができなくなる。その結果、クエン酸回路での脱水素酵素の補酵素であるNAD⁺やFADの不足に伴ってクエン酸回路での脱水素反応は進行しなくなり、クエン酸回路も停止する。なお、解糖系では、酸素の供給がなくなるとピルビン酸を乳酸に変えてNADHをNAD⁺に戻すため、反応は停止しない。"},
{id:418,ch:7,lv:0,q:"呼吸商とはどのような値か。次の語をすべて用いて40字以内で説明せよ。",k:["酸素","二酸化炭素","体積"],s:"滋賀医科大改題",a:"生物が呼吸を行うときに放出する二酸化炭素と、外界から吸収する酸素との体積比。(38字)",c:"酸素に対する二酸化炭素の体積の割合",e:"生物が呼吸によって外界から吸収した酸素の体積に対する、放出した二酸化炭素の体積の割合を呼吸商(RQ)という。呼吸商の値は呼吸基質の種類によって異なり、呼吸基質が炭水化物、脂肪、タンパク質の場合の呼吸商の理論値は、それぞれ約1.0、0.7、0.8となる。"},
{id:419,ch:7,lv:1,q:"19世紀の科学者は、好気性細菌を利用して、緑藻類に単に光を当てる実験とプリズムを用いて光を分光して当てる実験を行っている。それぞれの実験結果と、そこから判明した事実を、「光合成」の語を用いて130字以内で説明せよ。",k:["光合成"],s:"東京農工大改題",a:"単に光を当てたときは、酸素の多い場所に集まる好気性細菌が葉緑体の付近に多く集まり、葉緑体で光合成が行われ酸素が発生することがわかった。一方、光を分光して当てたときは、好気性細菌が青紫色光と赤色光の当たる付近に集まり、光合成には有効な波長の光があることが示された。(130字)",c:"好気性細菌が集まる 葉緑体 青紫色光 赤色光",e:"この実験は、1882年、エンゲルマンが糸状の緑藻類と酸素の多い場所に集まる性質をもつ好気性細菌を用いて行った実験である。緑藻類に単に光を当てた場合は、葉緑体付近に好気性細菌が集まり、葉緑体で光合成が行われて酸素が発生することがわかった。また、分光してさまざまな波長の光を当てた場合は、特に青紫色と赤色の光の当たる付近に好気性細菌が集まり、光合成ではこれらの波長の光がよく利用されていることがわかった。"},
{id:420,ch:7,lv:1,q:"光合成と呼吸とは、共通するしくみによりATP合成を行っている。そのしくみを50字以内で説明せよ。",k:[],s:"21. 岐阜大改題",a:"電子伝達系によって膜を挟んだH⁺の濃度勾配をつくり、この濃度勾配を利用してATP合成酵素を駆動させる。(50字)",c:"H⁺の濃度勾配 H⁺のATP合成酵素の通過 ATPの合成",e:"分布が偏って濃度勾配を生じたH⁺がその偏りを解消するために移動することが、ATP合成酵素の駆動力となる。このようなATP合成のしくみは、ミトコンドリアの内膜での酸化的リン酸化や、葉緑体のチラコイド膜の光リン酸化においてみられる。"},
{id:421,ch:7,lv:1,q:"C₄植物は、C₃植物よりも乾燥した場所での生育に適している理由を「蒸散」の語を用いて70字以内で説明せよ。",k:["蒸散"],s:"21. 岐阜大改題",a:"細胞内の二酸化炭素濃度が低くても効率よく二酸化炭素を固定することができるため、気孔の開口を減らして蒸散による水の損失を防ぐから。(65字)",c:"C₄回路で二酸化炭素を濃縮 低CO₂濃度での光合成速度が大きい",e:"C₄植物には、光合成に関与する細胞として、葉肉細胞と維管束鞘細胞の2つの異なるタイプの細胞がある。二酸化炭素は、葉肉細胞でホスホエノールピルビン酸(PEP)と結合しC₄化合物のオキサロ酢酸として固定される。オキサロ酢酸はリンゴ酸に変えられて、維管束鞘細胞に送られる。維管束鞘細胞に送られたリンゴ酸は、ピルビン酸となる。この過程で二酸化炭素が放出され、この二酸化炭素がカルビン回路で利用される。ピルビン酸は、葉肉細胞に戻って、PEPの再生に用いられる。このサイクルはC₄回路と呼ばれる。二酸化炭素とPEPの結合は、酵素PEPカルボキシラーゼが触媒となる。この酵素は、カルビン回路の酵素ルビスコに比べ、低い二酸化炭素濃度でも極めて高い活性を示すため、高温や乾燥で気孔が閉じ、葉の二酸化炭素濃度が低下した環境でも、効率よく二酸化炭素を固定することができる。"},
{id:422,ch:7,lv:1,q:"光合成に用いる色素以外で、光合成細菌が行う光合成と植物やシアノバクテリアが行う光合成のしくみの違いについて、100字以内で説明せよ。",k:[],s:"富山大改題",a:"光合成細菌は、光合成の電子供与体として硫化水素など水以外の物質を利用するため、光合成によって酸素を放出しない。一方、植物やシアノバクテリアは、電子供与体として水を利用し、光合成によって酸素を放出する。(100字)",c:"光合成細菌の光合成…電子供与体が水以外で酸素を放出しない",e:"植物やシアノバクテリアの光合成では、光合成に必要なH⁺やe⁻を水から得ており、光合成によって酸素を発生する。一方、光合成細菌の光合成では、光合成に必要なH⁺やe⁻を硫化水素や水素など水以外の物質から得ており、光合成によって酸素は発生しない。このほか、植物やシアノバクテリアでは、光合成色素としてクロロフィルaをもち、2つの光化学系(光化学系I、II)が存在するのに対し、光合成細菌では、光合成色素としてバクテリオクロロフィルaをもち、植物の光化学系I、IIに似た光化学系の一方しか存在しない。また、紅色硫黄細菌、緑色硫黄細菌の光合成では、光合成によって硫黄(S)を遊離する。"},
{id:423,ch:7,lv:1,q:"ミトコンドリアのマトリックスで起こる反応過程と、内膜で起こる反応過程について、それぞれ説明せよ。",k:[],s:"",a:"マトリックスでは解糖系で生じたピルビン酸がアセチルCoAに変えられてクエン酸回路に入る。ここで、水の付加反応、脱水素反応や脱炭酸反応が起こり、水、二酸化炭素、NADH、FADH₂を生じる。内膜には電子伝達系やATP合成酵素が存在する。電子伝達系では、解糖系やクエン酸回路で生じたNADHやFADH₂からH⁺とe⁻が放出される。e⁻は内膜のシトクロム間を伝達され、これに伴ってH⁺が膜間腔に輸送される。膜間腔のH⁺が濃度勾配によりATP合成酵素を通してマトリックスへ移動する際に、ATPを生成する。e⁻は最終的に酸素に受け渡され、さらにH⁺と結合して水を生じる。",c:"マトリックス…クエン酸回路。内膜…電子伝達系やATP合成酵素",e:"呼吸の過程は、解糖系、クエン酸回路、電子伝達系の3段階に分けられる。解糖系は、細胞質基質で進行し、グルコースが酸素を用いずに2分子のピルビン酸に分解される。クエン酸回路は、ミトコンドリアのマトリックスで進行する。電子伝達系は内膜上で進行する。内膜上に存在するATP合成酵素は輸送されたH⁺の移動によって、グルコース1分子につき最大34分子のATPを合成する。このようなATPの合成反応は、酸化的リン酸化と呼ばれる。"},
{id:424,ch:8,lv:0,q:"PCR法で用いられるDNAポリメラーゼの特徴を次の語をすべて用いて30字以内で説明せよ。",k:["好熱菌","最適温度","失活"],s:"",a:"好熱菌から得られ、最適温度が高く95℃でも失活しない。(26字)",c:"好熱菌由来のDNAポリメラーゼの性質",e:"約95℃に加熱することで塩基間の水素結合を可逆的に切断することができる。このとき、多くの種がもつDNAポリメラーゼでは、高温によって失活してしまう。好熱菌は、熱水噴出孔や温泉など高温環境下で生育しており、これらがもつDNAポリメラーゼは最適温度が高く、95℃でも失活しない。好熱菌のDNAポリメラーゼが発見され、使用されるようになったことでPCR法によるDNAの増幅が容易に行えるようになった。"},
{id:425,ch:8,lv:0,q:"電気泳動法において、DNA断片の長さに応じて移動する距離に差が生じる原理を「分子量」の語を用いて60字以内で説明せよ。",k:["分子量"],s:"",a:"ゲルの内部は、繊維が網目状になっているため、分子量の小さい物質は移動しやすく、大きい物質は移動しにくくなっている。(57字)",c:"分子量が小さい物質は速く、大きい物質は遅く移動する",e:"電気泳動法では、寒天やアクリルアミドなどのゲルを用いて電流を流すことで、物質を分離する方法である。ゲルの内部は繊維が網目状になっているため、分子量の大きい物質は引っかかりやすく移動速度は小さくなる。逆に、分子量の小さい物質は移動速度が大きくなる。DNAだけでなく、タンパク質も電気泳動で分離することができるが、複雑な立体構造をもつことやDNAのように負に帯電しているわけではないため、薬品を用いて、立体構造をほどいたり、負に帯電させたりする必要がある。"},
{id:426,ch:8,lv:0,q:"遺伝子の発現について、DNAの塩基配列ではなく、RNAシークエンシングによってmRNAを調べることの利点を次の語をすべて用いて40字以内で説明せよ。",k:["発現","細胞","発現量"],s:"",a:"細胞や組織ごとに発現している遺伝子の種類とその発現量を比較することができる。(38字)",c:"発現の有無、発現量の違いを明らかにする",e:"mRNAは、タンパク質が合成される際につくられる。したがって、mRNAの存在を調べると、遺伝子の発現の有無の指標となる。DNAの塩基配列は基本的に同一個体であれば、その情報は同じである。そのため、異なる生物間や異なる個体間での比較にはDNAの塩基配列の比較が適している。一方、同一個体における細胞や組織での遺伝子の発現の有無や発現量の比較には、RNAを調べることが適している。"},
{id:427,ch:8,lv:0,q:"トランスジェニック植物を作成する際に、ある除草剤に対して耐性となる遺伝子を目的の遺伝子とともにプラスミドに組み込んでおくと、作成した植物を効率よく取得することができる。その理由を、次の語をすべて用いて70字程度で述べよ。",k:["培地","除草剤","排除"],s:"東京大改題",a:"遺伝子が導入された個体のみが除草剤耐性をもつので、培地に除草剤を入れておけば、遺伝子が導入されなかった個体を選択的に排除することができるから。(71字)",c:"導入されなかった個体のみを選択的に排除",e:"一般に、遺伝子組換え操作を行っても遺伝子が導入される確率はきわめて低く、多くが導入されていない個体となる。植物では除草剤耐性遺伝子、細菌では抗生物質耐性遺伝子などを目的遺伝子とともに組み込めば、遺伝子が導入されなかった個体のみを選択的に排除することができ、効率よく目的の個体を得ることができる。このように、特定の生物を選択的に得る手法を、一般にスクリーニングという。その他のスクリーニングの手法としては、GFP(緑色蛍光タンパク質)の遺伝子を目的の遺伝子と一緒に組み込むことで、遺伝子導入がなされた組織が蛍光を発するのを利用し、遺伝子導入を確認することが広く行われている。"},
{id:428,ch:8,lv:0,q:"現在、日本をはじめ、多くの国で遺伝子治療が行えるのは、倫理的な問題などによって特定の体細胞に限られている。これに関して、特定の体細胞に限っている理由を、次の語をすべて用いて50字以内で述べよ。",k:["生殖細胞","胚","次世代"],s:"",a:"生殖細胞や胚への遺伝子治療は、取り込まれた遺伝子が次世代へ受け継がれる可能性があるため。(44字)",c:"次世代へ影響が及ぶ可能性",e:"病気の治療のため、遺伝子または遺伝子を導入した細胞をヒトの体内に投与したり、特定の塩基配列を標的としてヒトの遺伝子を改変したりすることを遺伝子治療という。遺伝子治療が認められているのは体細胞のみであり、生殖細胞や胚といった次世代への影響がある細胞への治療は認められていない。これは、都合のいいように個体発生に手を加えるという倫理的な問題や、将来に渡って遺伝子が受け継がれ、現時点で予期できない影響が生じ、その影響を制御することが極めて困難な事態に陥ることが強く懸念されているためである。"},
{id:429,ch:8,lv:0,q:"近年のヒトゲノム計画の発展によって、個人のゲノムを解明することが可能になった。これにより、どのような問題が生じる可能性があると考えられるか。次の語をすべて用いて、50字以内で説明せよ。",k:["疾病","個人情報"],s:"徳島大改題",a:"遺伝子から疾病の可能性などもわかり、この個人情報が流出すれば、差別につながる可能性がある。(45字)",c:"遺伝子は個人情報 病気のかかりやすさもわかる",e:"現在では、DNAレベルの解析から、遺伝病のみならず、疾病のかかりやすさ等のさまざまな情報が明らかになりつつある。このような個人のゲノム情報は、きわめて重要な個人情報であり、流出や悪用が起こらないよう、十分に気を付ける必要がある。"},
{id:430,ch:8,lv:1,q:"遺伝子組換えにおいて、目的の遺伝子を切り出す場合とプラスミドを切る場合は同じ種類の制限酵素を使用する理由を120字以内で説明せよ。",k:[],s:"20. 東京医科歯科大改題",a:"プラスミドに目的の遺伝子を結合させるには、目的の遺伝子とプラスミドのそれぞれの接合部が相補的な塩基配列をもつ必要がある。そこで、同じ塩基配列を切断する制限酵素を用いると、接合部を相補的な塩基配列にすることができるため。(109字)",c:"制限酵素の切断面が一致する",e:"制限酵素は、作用する塩基配列が決まっているため、目的の遺伝子の切断とプラスミドの切断を同じ種類の制限酵素で行うと、切断面の塩基配列が同じになる。そのため、お互いの切断面の塩基配列が相補性をもつことになり、結合させることができる。結合する際には、DNAリガーゼを用いる。"},
{id:431,ch:8,lv:1,q:"PCRは3つの温度(95℃、60℃、72℃)をくり返すことで、鋳型DNAから増幅される。それぞれの温度で起こる反応について110字以内で説明せよ。",k:[],s:"19. 関西学院大改題",a:"95℃では塩基間の水素結合が切断され、DNAが1本鎖に解離する。60℃では解離した1本鎖DNAに、相補的な配列のプライマーが結合する。72℃ではDNAポリメラーゼの働きでプライマーに続くヌクレオチド鎖が合成される。(104字)",c:"PCR法の温度は各反応が起こるのに最適な温度",e:"PCR法は、DNAの解離、プライマーの結合、伸長反応の3段階を1サイクルとし、これをくり返すことで鋳型DNAから目的の領域を増幅する手法である。1サイクル中で温度を変化させるのは、各反応が起こるのに最適な温度が異なるためである。約95℃では二本鎖DNAの塩基間の水素結合を可逆的に切断する。約60℃では塩基間の水素結合が再び形成され、相補的なプライマーを結合させる。約72℃では好熱菌由来のDNAポリメラーゼの活性が高まる温度で、伸長反応が効率よく進む。"},
{id:432,ch:8,lv:1,q:"遺伝子組換えの技術を利用してのインスリンの産生が、ブタやウシのすい臓からのインスリン精製より優れている点を、100字以内で答えよ。",k:[],s:"岡山県立大改題",a:"大腸菌などを利用するため、効率よくインスリンを産生することができる。また、ヒトのものとアミノ酸配列が同じインスリンを産生するため、ブタやウシのインスリンと違い、抗体がつくられる危険性が低い。(96字)",c:"アミノ酸配列が同じ 抗体 効率がよい",e:"ウシやブタのすい臓には少量のインスリンしか含まれず、インスリン以外の物質も多いため精製は容易ではない。ヒトインスリンは、遺伝子組換え技術を利用してできた最初の医薬品であり、増殖速度が大きく培養の容易な大腸菌などの微生物を用いることによって、効率よく大量のインスリンを産生できるようになった。また、インスリンのアミノ酸配列は、ウシのものでは3か所が、ブタのものでは1か所が、それぞれヒトのものとは異なる。このため、ウシやブタのインスリンは、ヒトの体内で異物と認識され、それらに対する抗体がつくられる可能性がある。"},
{id:433,ch:8,lv:1,q:"iPS細胞を医療に応用する場合、ES細胞に比べてどのような長所があるか。また、どのような問題点があるか。250字以内で述べよ。",k:[],s:"滋賀医科大改題",a:"ES細胞は、初期胚の将来胎児になる部分を利用するので、これを医療に使うことには倫理的な問題があるが、iPS細胞は体細胞を利用するので、そのような問題は生じない。また、ES細胞からつくった臓器などを移植する場合は、他人の細胞なので拒絶反応が起こる可能性が高いが、自己の体細胞からつくられたiPS細胞によって形成された臓器であれば、拒絶反応は起こりにくいと考えられる。一方、作製の際に使用する遺伝子やベクターの性質から、iPS細胞はがん化する危険性が高いことが指摘されている。(231字)",c:"ES細胞…他者の胚細胞由来 iPS細胞…(自己の)体細胞由来",e:"ES細胞(胚性幹細胞)は、哺乳類の初期胚(胚盤胞)から将来胎児となる部分(内部細胞塊)の細胞を取り出し、全能性をもったまま培養をし続けることができるようにしたものである。これに対し、iPS細胞(人工多能性幹細胞)は、山中伸弥らによってつくられた、さまざまな細胞に分化する能力(多能性)をもつ細胞である。ヒトiPS細胞は、ヒトの皮膚の細胞に4種類の遺伝子(通称「山中ファクター」)を導入し、細胞を未分化な状態に戻す(初期化)ことで作製された。これらの遺伝子には、遺伝子を初期化して発生初期の未分化な状態に戻す働きと、未分化な状態を維持させる働きがある。これらはがん細胞にみられる性質であり、iPS細胞の作製にも発がん性に関連のある遺伝子が用いられている。また、遺伝子導入の際に用いるレトロウイルスは、染色体内のランダムな位置に遺伝子を導入してしまうため、本来の遺伝子に変異を生じさせてがん化させてしまう可能性がある。"},
{id:434,ch:9,lv:0,q:"調節タンパク質とは何か、次の語をすべて用いて90字以内で説明せよ。",k:["調節遺伝子","転写調節領域","アクチベーター","リプレッサー"],s:"",a:"調節遺伝子から転写・翻訳され、DNA上の転写調節領域に結合することで遺伝子発現を促進または抑制するタンパク質で、促進するものをアクチベーター、抑制するものをリプレッサーと呼ぶ。(88字)",c:"転写調節領域に結合 遺伝子発現を調節",e:"遺伝子の発現では、発現の有無や転写されるRNA量が、さまざまな因子によって調節されている。転写調節領域とは、遺伝子の発現調節に関わるDNA領域のことをいう。"},
{id:435,ch:9,lv:0,q:"ハウスキーピング遺伝子とは何か、次の語をすべて用いつつ、例を挙げて65字以内で説明せよ。",k:["生命活動","細胞の種類"],s:"",a:"細胞の生命活動の維持に関与し、細胞の種類に関わらず、すべての細胞で発現している遺伝子で、RNAポリメラーゼなどが挙げられる。(62字)",c:"細胞の生命活動の維持に関与 すべての細胞で発現",e:"細胞の生命活動維持に関与する遺伝子は、家事や施設の維持管理になぞらえてハウスキーピング遺伝子と呼ばれている。DNAポリメラーゼや呼吸に関する酵素の遺伝子などが挙げられ、正常な細胞では常に一定量が発現している。"},
{id:436,ch:9,lv:0,q:"母性因子とは何か、次の語をすべて用いて50字以内で説明せよ。",k:["母体","卵","発生"],s:"",a:"母体の細胞内で合成されて、卵に貯えられたmRNAなどの物質のうち、発生過程に影響を及ぼすもの。(43字)",c:"母体で合成 卵に貯蔵 発生に影響",e:"ショウジョウバエのビコイドmRNAやナノスmRNAは、母性因子の例である。母性因子は体軸の決定など、初期発生において大きな役割を果たす。mRNAだけではなく、タンパク質として卵に含まれているものもある。"},
{id:437,ch:9,lv:0,q:"プログラム細胞死とは何か、細胞死の様式に言及し、次の語をすべて用いて80字以内で説明せよ。",k:["発生過程","核","DNA"],s:"",a:"発生過程のある段階で起こるように遺伝的に予定されている細胞死で、多くは核の崩壊とDNA断片化をともなうアポトーシスと呼ばれる形態で引き起こされる。(73字)",c:"遺伝的に予定された細胞死 アポトーシス",e:"ヒトやニワトリなどの発生過程で指が形成されるときに、水かきの部分の細胞が消失していく現象がみられる。このような発生過程であらかじめプログラムされた細胞死をプログラム細胞死といい、その多くはアポトーシスによって起こる。アポトーシスは特定の受容体を介したシグナル伝達などで誘導され、核の崩壊や細胞の断片化などの形態的特徴を示し、炎症を伴わない。アポトーシスは自己反応性の免疫細胞の排除などでもみられる。"},
{id:438,ch:9,lv:0,q:"誘導の連鎖の例として、眼の形成があげられる。イモリの尾芽胚期に神経管から眼の基本構造が完成するまでの過程を、次の語をすべて用いて90字以内で説明せよ。",k:["眼胞","水晶体","角膜","表皮","網膜"],s:"滋賀医科大改題",a:"神経管の前方は脳に分化し、脳の一部が左右にふくらんで1対の眼胞を生じる。眼胞は眼杯となって表皮から水晶体を誘導するとともに、網膜に分化する。さらに、水晶体は表皮から角膜を誘導する。(90字)",c:"眼胞・眼杯の誘導による水晶体の分化 水晶体の誘導による角膜の分化",e:"眼の形成では、まず、原口背唇が形成体として働き、外胚葉から神経管を誘導する。神経管の一部からできた眼胞は眼杯となり、水晶体を誘導する形成体として働く。さらに、水晶体が形成体となって角膜を誘導する。"},
{id:439,ch:9,lv:1,q:"多細胞動物での精子形成過程と卵形成過程の異なる点を110字以内で述べよ。",k:[],s:"18. 東京医科歯科大改題",a:"精子は、1個の一次精母細胞が均等に分裂して生じた4個の精細胞が変形して生じる。一方、卵は、1個の一次卵母細胞が、不均等分裂で二次卵母細胞と第一極体を生じ、さらに二次卵母細胞が不均等分裂で第二極体とともに生じる。(105字)",c:"精子形成では均等 卵形成では不均等な分裂",e:"精子形成過程での減数分裂は均等な分裂で、生じた精細胞が変形することで精子が生じる。一方で、卵形成においては、細胞質の不均等な分裂で卵が生じ、残りの極体はやがて退化する。この過程で、発生に必要な栄養分や、母性因子が卵に蓄積する。"},
{id:440,ch:9,lv:1,q:"哺乳類における、一般の体細胞分裂と卵割の大きな違いは何か。40字以内で述べよ。",k:[],s:"東京大改題",a:"G₁期やG₂期がなく、細胞周期が短い。各割球は成長せず、初期には同調分裂を行う。(38字)",c:"割球が成長せず分裂を続ける 短い細胞周期 同調分裂",e:"一般的な細胞周期では、M期に生じた2個の細胞は、間期を通じてもとの細胞の大きさに成長しながら、S期にDNAを複製し、G₂期に分裂の準備を終えて再びM期に入る。一方、動物の卵割時にみられる細胞周期は、ふつうG₁期とG₂期を欠き、通常の体細胞分裂の細胞周期に比べて速く進行する。初期の卵割では、各割球がほぼ同時に分裂(同調分裂)するので、n回卵割が起こると割球の数は2のn乗個に増加する。"},
{id:441,ch:9,lv:1,q:"バイソラックス突然変異体およびアンテナペディア突然変異体の形態的特徴について、それぞれ簡潔に説明せよ。",k:[],s:"福岡教育大",a:"パイソラックス突然変異体は、胸部が二重になった結果、2対の翅をもつ突然変異体であり、アンテナペディア突然変異体は、触角が形成される位置に脚が形成された突然変異体である。(85字)",c:"二重の胸部に2対の翅 触角に脚",e:"ホメオティック遺伝子の突然変異により、からだの各構造が本来形成されるべき位置に形成されず、別の構造に置き換わった個体を、ホメオティック突然変異体という。パイソラックス突然変異体やアンテナペディア突然変異体は、ホメオティック遺伝子に突然変異が起こった結果、その調節を受ける一連の遺伝子の発現が変化することによって生じる。"},
{id:442,ch:9,lv:1,q:"ゼブラフィッシュの原腸胚における背腹軸形成には、胚の腹側で産生される分泌タンパク質BMPと、背側で産生される分泌タンパク質コーディンが重要な役割を果たしている。あるBMPタンパク質の遺伝子欠失変異体では、腹側組織が縮小して背側組織が増大した。一方、コーディン遺伝子の欠失変異体では、背側組織が縮小して腹側組織が増大した。このとき、コーディン、BMP遺伝子の両方が欠失した二重変異体は、コーディン変異体かBMP変異体のどちらかの胚と同じ形態を示した。どちらの変異体の胚と同じ形態を示すと考えられるか、理由も含めて140字以内で述べよ。",k:[],s:"20. 名古屋大改題",a:"コーディンはBMPと結合することでBMPの作用を阻害するので、コーディン変異体ではBMPが作用する。一方、BMP変異体ではBMPが発現せず、その作用はない。二重変異体ではBMPが発現せず、BMPの作用がないため、BMP変異体と同様の形態の胚になると考えられる。(130字)",c:"コーディンはBMPに結合してBMPと受容体の結合を阻害",e:"脊椎動物において、神経誘導のしくみに関与するコーディンとBMPは、コーディンが背側で発現することによって、BMPと受容体との結合を阻害して背側構造の形成(神経の形成)に働く。コーディン変異体ではこの阻害が起こらないため、背側が縮小、腹側が増大した表現型が現れると考えられる。一方、BMP変異体では、BMPの作用が起こらないため腹側が縮小、背側が増大した表現型が現れると考えられる。したがって、二重変異体では、BMPの欠失により、BMPの作用が起こらないため、コーディンの作用に関わらず、BMP変異体の表現型が現れると考えられる。"},
{id:443,ch:10,lv:0,q:"有髄神経繊維と無髄神経繊維で興奮の伝導速度を比較すると、有髄神経繊維の方が速い。その理由を次の語をすべて用いて65字以内で答えよ。",k:["髄鞘","絶縁性","ランビエ絞輪"],s:"",a:"有髄神経繊維には電気的に絶縁性の高い髄鞘があり、髄鞘におおわれていないランビエ絞輪間を跳躍するように興奮が伝わるため。(59字)",c:"絶縁性が高い髄鞘 ランビエ絞輪 跳躍伝導",e:"有髄神経繊維の髄鞘は絶縁性が高く電流を通しにくい。そのため、局所電流はランビエ絞輪を飛び飛びに跳躍伝導していくことになり、伝導速度が大きくなる。無髄神経繊維は髄鞘がなく、軸索の興奮部から隣接する静止部に向かって、次第に伝わっていくため遅い。伝導速度は、髄鞘の有無だけではなく、軸索の直径によっても変わる。"},
{id:444,ch:10,lv:0,q:"ウマでは赤を見分けることができない。このことから考えられるウマの視細胞の特徴を「錐体細胞」の語を用いて、ヒトの視細胞と比較して50字以内で説明せよ。",k:["錐体細胞"],s:"",a:"ヒトは赤色光を受容する錐体細胞をもつが、ウマはそのような錐体細胞をもたないと考えられる。(44字)",c:"赤、緑、青は異なる錐体細胞で受容される",e:"ヒトの場合、赤錐体細胞、緑錐体細胞、青錐体細胞の3種類があるが、ウマは赤色が認識できないことから、ヒトがもつような赤錐体細胞の欠如が考えられる。これはサルのなかま以外のほとんどの哺乳類でみられる2色型色覚である。"},
{id:445,ch:10,lv:0,q:"トロポニンにカルシウムイオンが結合した後に生じるアクチンフィラメントの変化について、次の語をすべて用いて50字以内で答えよ。",k:["ミオシン結合部位","トロポミオシン"],s:"",a:"トロポミオシンが移動することで隠れていたミオシン結合部位が露出して、ミオシン頭部と結合する。(46字)",c:"トロポミオシンの移動 ミオシン結合部位の露出",e:"筋小胞体からのカルシウムイオンがトロポニンに結合すると、ミオシン結合部位を隠していたトロポミオシンが移動する。それによって、アクチンフィラメントのミオシン結合部位が露出し、ミオシン頭部と結合できるようになる。結合後にミオシン頭部が屈曲し、アクチンフィラメントが滑走してサルコメアの長さが短くなる(筋収縮)。"},
{id:446,ch:10,lv:0,q:"短時間の激しい運動では、クレアチンリン酸が利用される。そのときの、クレアチンリン酸の役割について、次の語をすべて用いて35字以内で説明せよ。",k:["リン酸","ATP","再合成"],s:"20. 鳥取大改題",a:"クレアチンリン酸がADPにリン酸を渡すことでATPを直ちに再合成する。(31字)",c:"ADP リン酸 ATP 再合成",e:"筋繊維内には、ほんの数秒で使い切る程度のATPしか蓄えられていないので、ADPにリン酸を結合させ、直ちにATPを再合成する必要がある。クレアチンリン酸は、安静時にクレアチンとATPから合成される。筋収縮時にはクレアチンリン酸からリン酸をADPに受け渡し、ATPを再合成する。その結果、クレアチンリン酸によって盛んにATPが再合成され、運動が長く続く。"},
{id:447,ch:10,lv:0,q:"慣れの形成は、神経伝達物質の量が減ることによって起こる。神経伝達物質が減少する2つの原因を、次の語をすべて用いて70字以内で説明せよ。",k:["シナプス小胞","不活性化"],s:"",a:"感覚ニューロンのシナプス小胞の減少と、神経終末の電位依存性カルシウムチャネルが不活性化して神経伝達物質の放出が抑えられるため。(65字)",c:"シナプス小胞の減少 電位依存性カルシウムチャネルの不活性化",e:"慣れは、同じ刺激をくり返し与えると反応の強さや頻度が次第に減少していく現象である。慣れの形成にはシナプス小胞の減少や電位依存性カルシウムチャネルの不活性化が関与する。いずれも神経伝達物質の放出量が減少することにつながり、慣れが生じる。"},
{id:448,ch:10,lv:1,q:"刺激によって神経細胞に生じた興奮が脳に送られる際に、神経細胞間の情報伝達はシナプスを介して行われる。シナプスにおける神経伝達物質を用いた情報伝達のしくみを次の語をすべて用いて、150字以内で説明せよ。",k:["シナプス前細胞","カルシウムイオン","シナプス後細胞"],s:"20. 大阪市立大改題",a:"興奮がシナプス前細胞の神経終末に伝わると、電位依存性カルシウムチャネルからカルシウムイオンが流入し、シナプス小胞内の神経伝達物質がエキソサイトーシスによってシナプス間隙に放出される。シナプス後細胞では、神経伝達物質が受容体に結合してイオンチャネルが開き、膜電位が閾値に達して活動電位が生じる。(146字)",c:"神経終末 カルシウムイオン シナプス小胞 シナプス間隙 神経伝達物質 受容体",e:"神経終末に興奮が伝わると、電位依存性カルシウムチャネルが開き、カルシウムイオンが流入する。カルシウムイオンが神経終末に入ると、エキソサイトーシスが起こってシナプス小胞に包まれた神経伝達物質が、シナプス間隙に放出される。アセチルコリンやノルアドレナリンやグルタミン酸などの神経伝達物質は、シナプス後細胞の伝達物質依存性イオンチャネルに結合し、ナトリウムイオンなどを細胞内に流入させる。これによって、シナプス後細胞での膜電位が閾値に達し、活動電位を生じる。"},
{id:449,ch:10,lv:1,q:"天文愛好家は、望遠鏡の視野の中心にある淡い星を見るときに、そらし目(視野の中心ではない部位を見ること)で観察するとよく見えることを知っている。そらし目で観察するとよく見えるのは、視細胞の機能と分布のどのような特徴によるものか、次の語をすべて用いて80字以内で説明せよ。",k:["黄斑","周辺","視野の中心"],s:"21. 同志社大改題",a:"視野の中心には弱い光では反応しにくい錐体細胞が集まった黄斑があり、視野の中心から外れた黄斑の周辺には弱い光でも反応できる桿体細胞が多く分布していることによる。(79字)",c:"黄斑は錐体細胞が多い 黄斑の周辺部は桿体細胞が多い",e:"黄斑は、網膜の中心にあり、ヒトが注視しているときの視野の中心となる。このような構造の特徴から、暗い星を見るときに、その星を直視してしまうと黄斑で光をとらえることになる。黄斑の中心に近づくほど、桿体細胞の数が減って中心付近では錐体細胞だけとなる。したがって、黄斑の中心では弱い光を捉えることが難しくなっている。桿体細胞は、弱い光でも反応するため、黄斑の周辺部に分布する桿体細胞を使うことで、暗いところでの明暗を見分けることができ、暗い星でも見ることができる。"},
{id:450,ch:10,lv:1,q:"宇宙ステーション内では、前庭と半規管の働きは地上とどのように異なるか。考えられることを150字以内で述べよ。",k:[],s:"20. 滋賀医科大改題",a:"からだの傾きは、前庭内の平衡石がからだの傾きに応じて重力に従って動き、感覚毛が倒れることによって感知される。無重力状態では平衡石が動かないため、傾きを感知することはできない。一方、無重力状態にあっても体が回転すると慣性でリンパの流れが生じ、感覚毛が倒れるため、回転方向を感知することができる。(146字)",c:"前庭 平衡石 重力 半規管 回転",e:"平衡(からだの傾き)と回転は、それぞれ内耳の前庭と半規管によって受容される。前庭に集まった有毛細胞の感覚毛は、ゼリー状の物質に覆われており、このゼリー状の物質の上に平衡石(耳石)がのっている。重力のある場所では平衡石の重さによって、ゼリー状の物質が押されて感覚毛が倒れて、傾きを感知する。無重力状態では平衡石に重力がかからないため、傾きを感知することはできない。一方、半規管のリンパ液は回転の慣性により流れが生じる。半規管の一端の膨大部に有毛細胞が集まっており、ここでの感覚毛は、クプラと呼ばれるゼリー状の物質によって包まれている。リンパの流れによってクプラが押されると感覚毛が倒れて、回転を感知する。無重力状態においても慣性は働くので、回転は感知できる。"},
{id:451,ch:11,lv:0,q:"被子植物のおしべの葯では花粉母細胞から花粉が形成される。この花粉が完成するまでの過程を次の語をすべて用いて80字以内で説明せよ。",k:["花粉母細胞","花粉","減数分裂","体細胞分裂"],s:"",a:"おしべの葯に存在する花粉母細胞が減数分裂をして花粉四分子が形成される。花粉四分子はそれぞれが体細胞分裂を行い、雄原細胞と花粉管細胞となり花粉が完成する。(76字)",c:"花粉母細胞が減数分裂をして花粉四分子になる",e:"花粉母細胞から花粉が形成される過程を説明するので、どの段階で減数分裂を行っているのかを明らかにして書く必要がある。特に指定された語のなかに、「減数分裂」と「体細胞分裂」があるため、より明確に、どの細胞が減数分裂することによって何になるのかを示す必要がある。花粉母細胞から花粉が形成される過程において、DNA量が半分になる減数分裂が起こるのは、花粉四分子が形成されるときである。その後は、DNA量は変化せず、不均等な分裂ではあるが体細胞分裂と同じ過程を経て、雄原細胞と花粉管細胞ができ、花粉が完成する。"},
{id:452,ch:11,lv:0,q:"光発芽種子では、赤色光と遠赤色光がフィトクロムに受容されることで発芽が調節される。光発芽種子における発芽調節のしくみについて、次の語をすべて用いて80字以内で説明せよ。なお、PfrとPrは1字として数えること。",k:["赤色光","遠赤色光","Pfr型","Pr型","発芽"],s:"",a:"種子に赤色光が当たると、フィトクロムがPfr型となり、発芽が促進される。一方、種子に遠赤色光が当たると、フィトクロムがPr型となり、発芽が抑制される。(71字)",c:"赤色光が当たる→フィトクロムがPfr型に→発芽促進",e:"光発芽種子における発芽調節のしくみについて問われているため、発芽を促進する場合と発芽を抑制する場合の両方を書く。光発芽種子は、赤色光によって発芽が促進され、遠赤色光によってその効果が打ち消される。これは、光受容体であるフィトクロムが、赤色光を受けるとPfr型(遠赤色光吸収型)に、遠赤色光を受けるとPr型(赤色光吸収型)に、可逆的に変化することで起こる。"},
{id:453,ch:11,lv:0,q:"屈性と傾性の違いを、次の語をすべて用いて65字以内で説明せよ。",k:["屈曲","刺激の方向"],s:"",a:"刺激の方向に対して一定の方向に屈曲する性質を屈性といい、刺激の方向とは無関係に一定の方向に屈曲する性質を傾性という。(58字)",c:"屈性…刺激の方向に対する一定方向の屈曲。傾性…刺激の方向と無関係な一定方向の屈曲",e:"屈性には、重力屈性や光屈性がある。刺激を受けた方向に屈曲することを正の屈性、刺激を受けた方向と逆に屈曲することを負の屈性という。傾性は、刺激の方向とは無関係に起こる。傾性の例として、チューリップが日中の気温上昇に伴って花が開くことや、オジギソウが葉に接触があると急速に葉を閉じることなどがある。"},
{id:454,ch:11,lv:0,q:"シロイヌナズナにおいて、フロリゲンはどこで合成され、どこを通って茎頂に運ばれるか。次の語をすべて用いて35字以内で説明せよ。",k:["フロリゲン","合成","輸送","茎頂"],s:"",a:"フロリゲンは葉で合成され、師管を通して茎頂に輸送される。(28字)",c:"フロリゲンは葉で合成される。師管を通して茎頂に運ばれる。",e:"気温や日長条件などが整えば、フロリゲンが葉で合成される。その後、師管を通して茎頂に運ばれ、そこで花芽の形成を促進する。この事実を示す実験として、オナモミを用いた短日処理実験と、環状除皮実験が有名である。フロリゲンとして働く物質は、植物によって異なっており、シロイヌナズナではFTタンパク質が、イネではHd3aがフロリゲンの正体であることがわかっている。"},
{id:455,ch:11,lv:1,q:"重複受精とは何か。130字以内で説明せよ。",k:[],s:"21. 東京学芸大",a:"被子植物の受精の過程において、雄原細胞から生じた2つの精細胞のうち、一方は卵細胞と融合して受精卵となり、もう一方は中央細胞と融合し胚乳細胞となる。このように、精細胞と卵細胞、精細胞と中央細胞の融合が同時に起こるような受精様式のことを重複受精という。(124字)",c:"2つの精細胞のうち、一方は卵細胞と、もう一方は中央細胞と融合する",e:"被子植物では、2つの精細胞のうち、一方は卵細胞と融合して受精卵となり、もう一方は中央細胞と融合し胚乳細胞となる。このように、細胞の融合が同時に起こるような受精様式のことを重複受精という。イチョウなどの裸子植物ではみられない。重複受精が起こる利点については、重複受精を行わない裸子植物は受精の有無にかかわらず胚乳が発達するのに対して、重複受精では卵細胞と精細胞が正常に受精した場合のみ胚乳が発達するため、エネルギーロスが少ないという利点があると考えられている。"},
{id:456,ch:11,lv:1,q:"赤色光下においた野生型のシロイヌナズナに弱い青色光を照射すると、葉面温度の低下が観察された。その理由を40字以内で述べよ。",k:[],s:"21. 法政大改題",a:"青色光により気孔が開いて蒸散が起こる。このときの気化熱として熱が奪われたため。(40字)",c:"青色光で気孔が開く。蒸散によって葉面温度が低下する。",e:"青色光には、気孔を開口させる効果がある。このしくみには、葉に存在するフォトトロピンが関与する。フォトトロピンが青色光を受容すると、孔辺細胞の膨圧が上昇して孔辺細胞が変形し、気孔が開く。気孔が開くと蒸散が起こるため、気化熱によって葉面温度が低下する。"},
{id:457,ch:11,lv:1,q:"マカラスムギの幼葉鞘は正の光屈性を示す。このしくみについてオーキシンの移動に着目し、次の語句をすべて用いて120字以内で説明せよ。",k:["オーキシン","合成","光の当たる側","光の当たらない側","移動","細胞成長"],s:"",a:"オーキシンは幼葉鞘の先端で合成され、下降して細胞成長を促進する。幼葉鞘の先端に一方から光が当たると、オーキシンは光の当たらない側に移動してから下降し、その部分の細胞成長を促進する。その結果、幼葉鞘は光の当たる側に屈曲する。(111字)",c:"オーキシンは先端で合成され、光の当たらない側に移動する",e:"オーキシンは、細胞の伸長成長を促進する植物ホルモンである。マカラスムギの幼葉鞘では、先端部でオーキシンが合成される。一方から光を当てると、オーキシンを輸送する膜タンパク質が、光の当たらない側により多く分布するようになる。その結果、オーキシンが光の当たらない側により多く輸送されて、オーキシン濃度に偏りが生じる。これに伴って細胞の成長にも偏りが生じて、屈曲が起こる。"},
{id:458,ch:11,lv:1,q:"成熟したリンゴの果実と未熟なリンゴの果実を同じ容器の中に入れて密閉したところ、未熟なリンゴの果実も成熟した。未熟な果実が成熟した理由を70字以内で述べよ。",k:[],s:"21. 石川県立大",a:"成熟したリンゴの果実からは、未熟な果実を成熟させる働きがあるエチレンが放出されるため、同じ容器に入れていた未熟なリンゴの果実が成熟した。(68字)",c:"エチレンは果実の成熟を促進する",e:"エチレンは、果実の成熟を促進する働きのある植物ホルモンである。気体で働き、成熟したリンゴやバナナの果実から多く放出される。これらと未熟な果実を同じ容器内にしばらく入れておくと、エチレンによって果実は成熟する。エチレンには、他にも落葉・落果の促進、細胞の横方向への成長促進などの働きがある。"},
{id:459,ch:11,lv:1,q:"気孔が閉じるしくみを、次の語をすべて用いて100字以内で説明せよ。",k:["水","K⁺","アブシシン酸","膨脹","浸透圧"],s:"",a:"葉でアブシシン酸が合成されると、孔辺細胞からK⁺が大量に流出する。それに伴い孔辺細胞の浸透圧が低下する。引き続いて水の流出が起こり、その結果、孔辺細胞の膨圧が低下してその形状が変化し、気孔が閉じる。(98字)",c:"K⁺の大量流出 浸透圧の低下 水の流出 膨圧の低下 孔辺細胞の変形",e:"気孔は、1対の湾曲した孔辺細胞に囲まれた間隙であり、それらの孔辺細胞の形状の変化によって開閉する。植物が乾燥状態におかれると、アブシシン酸が急激に合成される。その結果、孔辺細胞からカリウムイオン(K⁺)の流出が起こり、浸透圧が低下する。引き続いて水が流出し、膨圧が低下して、気孔から遠い側(外側)の湾曲が緩和され、気孔が閉じる。逆に、孔辺細胞へK⁺が流入すると浸透圧が上昇し、引き続いて水の流入が起こり、膨圧が上昇して外側の湾曲が大きくなり、気孔が開く。"},
{id:460,ch:11,lv:1,q:"植物体内のオーキシンの移動には方向性がある。オーキシンの下方への移動について、方向性が生じるしくみを次の語をすべて用いて150字以内で説明せよ。",k:["細胞膜","輸送タンパク質","基部側"],s:"21. 工学院大改題",a:"オーキシンを細胞外に放出する輸送タンパク質は、細胞の基部側に局在し、オーキシンを細胞内に取り込む膜タンパク質はそれ以外の領域に分布している。その結果、細胞外から取り入れられたオーキシンが、細胞の基部側の細胞膜から排出される。このため、オーキシンの移動に方向性が生じる。(134字)",c:"オーキシンの移動の方向性は輸送タンパク質の局在による",e:"オーキシンは、光屈性や重力屈性をもたらす植物ホルモンである。オーキシンには、植物体の頂端側から基部側に向かってのみ移動するという性質がある。これを極性移動という。移動の方向性を決めているのは、細胞膜上に存在する膜タンパク質である。オーキシンを細胞内に取り込むAUXタンパク質は細胞の頂部側に多く、細胞外に放出するPINタンパク質は、細胞の基部側に局在している。これにより、オーキシンは先端部から基部に向かって移動する。"},
{id:461,ch:12,lv:0,q:"個体数は無制限にふえることはなく途中から頭打ちになる。その理由について、次の語をすべて用いて60字以内で述べよ。",k:["密度","不足"],s:"",a:"高密度では、食物や生活空間の不足等の密度効果が働き、出生率と死亡率が等しくなって、個体数が一定になるから。(53字)",c:"成長曲線 密度効果 食物や生活空間の不足",e:"ある個体群における個体数の増加は個体群の成長と呼ばれ、個体群の成長を表すグラフは成長曲線と呼ばれる。食物や生活空間など、生存と繁殖に必要な資源に制限がない場合は、個体数は際限なくふえることができるため、成長曲線のグラフはJ字型(指数関数的な増加)を示す。しかし、このようなことは現実にはあり得ない。実際には、個体数が少ない初期には、個体数に対して食物や生活空間が十分に確保できるため、指数関数的な増加を示す。しかし、個体数が増加すると食物や生活空間が不足したり、排出物による汚染が進んだりして密度効果が働き、個体数の増加の割合は小さくなって、やがて頭打ちとなる。そのため、個体群密度は一定となり、成長曲線は全体としてS字型の曲線を描く。"},
{id:462,ch:12,lv:0,q:"植食性動物が群れをつくることは、個体にとってどのような有利な点があるか。次の語をすべて用いて60字以内で答えよ。",k:["警戒","採食","時間"],s:"",a:"群れ全体として捕食者を発見しやすくなるので、各個体が周囲を警戒する時間が短くなり、採食にかけられる時間が長くなる。(57字)",c:"捕食者の発見 警戒時間の減少 採食時間の増加",e:"個体数が多いと、捕食者に襲われても群れ全体が一度には食べ尽くされない。この利点は、配偶者の獲得や子育てが容易になることなど子を残すうえでも有利に働く。また、肉食性動物の場合は、協調した狩りを行うことによって食物を獲得しやすくなることも利点である。一方で、群れが大きくなるにつれ、食物の不足や個体間の争いの増加、感染症の蔓延などの不利な面も現れてくる。"},
{id:463,ch:12,lv:0,q:"生態的地位が類似した2種が、類似性を維持したまま長期間共存できるのはどのような場合か。次の語をすべて用いて50字以内で答えよ。",k:["資源","種間競争"],s:"",a:"すみわけや食いわけによって生活空間や食物等の資源を分割することで、種間競争を避けている場合。(46字)",c:"資源の分割 多種の共存",e:"複数種が同一の場所に生息する場合、それらの種の間でニッチ(生態的地位)が同じ、または近似しているとき、食物や生活場所などの資源をめぐっての競争が起こる。そこで、生活時間帯や生活空間を変えることによってニッチをずらし、互いに接して生活したり、同じ場所に共存したりする。この現象はすみわけと呼ばれる。また、食性を変えて共存している場合もあり、この場合は、食いわけと呼ばれる。これらは、基本ニッチから実現ニッチに変化する例の1つと考えられる。どちらの場合も、ニッチが完全に一致する種は共存できないという関係が基本となる。"},
{id:464,ch:12,lv:0,q:"生態系における物質の流れとエネルギーの流れの違いについて、次の語をすべて用いて60字以内で述べよ。",k:["炭素","窒素","熱","循環"],s:"新潟大改題",a:"炭素や窒素などの物質は生態系内を循環するが、エネルギーは循環せず、最終的に熱エネルギーとして生態系外に出る。(54字)",c:"物質は循環する ⇔ エネルギーは一方向に流れる",e:"生産者は、非生物的環境にある二酸化炭素や水などの無機物から有機物を生産する。生産者によって合成された有機物は、直接または間接的に消費者の栄養になる。また、生産者や消費者は呼吸によって二酸化炭素や水を放出したり、分解産物として無機塩類などをつくったりする。これらの無機物は、非生物的環境に戻され、再び生物群集に取り込まれる。このように、物質は生態系内で循環している。また、物質の循環に伴って、エネルギーの移動がみられる。生産者によって合成された有機物には、太陽の光エネルギーが化学エネルギーとして蓄えられている。この化学エネルギーは、食物連鎖の流れに従って一次消費者から高次の消費者に移り、それぞれの生物の生命活動に必要なエネルギーに利用される。このように、生物の生活に必要なエネルギーは、もとはすべて太陽の光エネルギーに由来する。最終的には熱エネルギーとして失われるので、エネルギーは生態系内を一方向に流れている。"},
{id:465,ch:12,lv:0,q:"個体群絶滅の要因にもなる近交弱勢とはどのようなことか、次の語をすべて用いて60字以内で説明せよ。",k:["遺伝子","交配","適応度"],s:"",a:"共通の遺伝子を多くもつ近親間で交配し、特定の病気にかかりやすいなどといった適応度の低下した個体が現れやすくなること。(58字)",c:"近親交配 適応度の低下",e:"個体数が減少した集団では、必然的に近親の個体と交配する機会が多くなる。近親の個体どうしは共通した遺伝子を多くもつため、近親交配では、特定の病気が発症しやすくなるような、生存や繁殖に不利な遺伝子(多くの場合、潜在の遺伝子)のホモ接合体が生じる確率が高くなる。集団内でこのような個体が増えると、集団全体としても次世代の個体を残しにくくなるため、近交弱勢は絶滅の一因になると考えられている。"},
{id:466,ch:12,lv:1,q:"ダイズの成長に伴う質量の変化を調べると、個体群の密度を変えたときに、単位面積当たりの個体群の質量が変化することが分かる。ただし、時間が経過すると、種子をまいたときの密度に関係なくほぼ一定の値になる。どのようなことが起こってこのような結果となったのか、130字以内で説明せよ。",k:[],s:"20. お茶の水大改題",a:"各個体が小さい間は、養分や光等の資源は各個体へ十分に供給されるので、高密度ほど個体群全体の質量は大きい。しかし、成長に伴い資源をめぐる競争が激しくなると、密度が高いほど各個体が利用できる資源が少なくなり、結果的に個体群全体の質量は密度によらず一定となる。(127字)",c:"最終収量一定の法則 個体群全体の質量は一定",e:"植物は移動しないので、利用する資源は根付いた場所で得られるものに限られる。同種、異種を問わず、周囲にある他個体は競争相手である。密度が高ければ高いほど、個体当たりの利用できる資源は減るが、植物群集全体としては得られる光エネルギーや同化の反応物となる養分等の量は変わらない。そのため、最終収量は密度に関わらずほぼ一定となる。なお、あまりに高密度の場合は、共倒れ(個体群全体が資源不足により枯死)したり、自己間引き(一部の個体が枯死することで、生存する個体に資源を集中する)したりすることもある。"},
{id:467,ch:12,lv:1,q:"縄張りとは何か。行動圏との違いが明確になるように80字以内で述べよ。",k:[],s:"18. 京都大改題",a:"動物個体が日常的に行動する空間を行動圏といい、そのなかでも特に採食や繁殖等を目的として、主に同種の他個体に対して排他的な行動をとり占有する空間を縄張りという。(79字)",c:"行動圏 縄張り 排他的な行動",e:"多くの動物は、一定の範囲内で移動をする。この範囲が行動圏であるが、一生涯不変ということではなく、環境や他個体との力関係によって変化していく。縄張りは行動圏の全部または一部であるが、これも不変ではない。なお、個体ではなく、つがいや群れとして縄張りをもつ例も多く知られている。"},
{id:468,ch:12,lv:1,q:"マメ科の植物の根に微生物との共生によってつくられる特別な構造の名称をあげて、その共生関係を130字以内で説明せよ。",k:[],s:"21. 高知工科大改題",a:"マメ科植物の根には、根粒菌が共生した根粒と呼ばれる構造がみられる。マメ科植物は、根粒菌に光合成産物である糖を与え、根粒菌は、窒素固定で生じた窒素化合物をマメ科植物に供給する。このように両者の相利共生の関係が成立している。(110字)",c:"根粒菌 マメ科植物 相利共生",e:"根粒菌はマメ科植物が生育していない土壌中にもふつうにみられる細菌だが、マメ科植物がいるとその根の中に取り込まれ根粒を形成する。根粒中の根粒菌は、マメ科植物が光合成で生産した栄養分を利用することができる。根粒内では、根粒菌が大気中の窒素をニトロゲナーゼによって還元しアンモニウムイオンに変えている。このような働きを窒素固定という。マメ科植物は、アンモニウムイオンの供給を受け、それを利用して同化を行うことができる。そのため、他の植物が生育しにくいような栄養分の少ない土壌でも、マメ科植物はよく成長する。双方の種に利益があるような共生関係を相利共生という。"},
{id:469,ch:12,lv:1,q:"浅海域と外洋域の単位面積当たりの年純生産量を比べた時に、浅海域が大きい理由と外洋域が小さい理由を、合わせて100字以内で説明せよ。",k:[],s:"21. 金沢大改題",a:"浅海域で純生産量が大きいのは、生産者が同化に利用する栄養塩類が、陸地から豊富に流入するためである。外洋域で純生産量が小さいのは、生産者のいる光の届く表層では栄養塩類が少ないためである。(92字)",c:"海洋における純生産量の違い 栄養塩類の量",e:"海洋全体で見れば、外洋域の純生産量が大きい。それは、浅海域と比べて圧倒的に広い面積があるからである。単位面積当たりの純生産量は、浅海域が大きいが、藻場やサンゴ礁は特に大きい。また、単位面積当たりの純生産量は湧昇域も大きい。外洋の深海には豊富な栄養塩類が存在し、その栄養塩類は深層海流に乗って流れている。湧昇域では湧昇流によって、栄養塩類が海底から表層までもち上げられるので、それを利用する植物プランクトンも豊富になる。"},
{id:470,ch:12,lv:1,q:"窒素や炭素は生態系のなかを循環している。炭素は動物と植物の間でどのように循環しているか、130字以内で説明せよ。",k:[],s:"20. 大阪市立大改題",a:"動物は、食物から吸収した有機物を呼吸によって分解し、生じた二酸化炭素を大気中に放出する。植物は、二酸化炭素を光合成によって有機物に固定する。植物体内の有機物を、動物が直接、または間接的に利用する。このように、炭素は動物と植物の間で循環している。(122字)",c:"呼吸 光合成 二酸化炭素 有機物",e:"生態系内では、菌類・細菌も生産者が生産した有機物を直接、または間接的に利用して生活している。また、火山活動や化石燃料の燃焼による二酸化炭素の放出等も炭素の循環に関わるが、本問は動物と植物の間の循環について問うているので、それ以外の要素は記述するべきではない。"},
{id:471,ch:12,lv:1,q:"遺伝的多様性の低下が個体群の絶滅を引き起こしやすくする理由を「環境の変化」という語を用いて、130字以内で説明せよ。",k:["環境の変化"],s:"18. 日本女子大改題",a:"遺伝的多様性が高い個体群は、環境の変化があっても新しい環境に適応して生存する個体が存在する可能性が高い。逆に、遺伝的多様性の低下した個体群は、環境が変化すると新たな環境に適応できる個体が存在する可能性が相対的に低い。そのため、絶滅する可能性が高くなる。(126字)",c:"遺伝的多様性の低下 環境の変化への適応 絶滅",e:"個体群の個体数が減ることは、遺伝子プールにある遺伝子の数が減ることを意味し、遺伝子の多様性の低下につながる。人間の活動による生息地の縮小や分断はその原因になり得る。今、多くの生物が絶滅の途上にあるのは、人間の行いのためだということを否定はできない。種内の遺伝的多様性が高ければ、生態系内の種の多様性も維持しやすくなる。種の多様性を保つためには、生態系の多様性が高いことも重要である。このように遺伝的多様性、種の多様性、生態系の多様性の3つは相互に関係しており、それぞれの多様性を保つことが生態系を支えることにつながる。"}
];

// ===================== ユーティリティ =====================
const store = {
  get(key, fallback) { try { const v = localStorage.getItem(key); return v === null ? fallback : JSON.parse(v); } catch { return fallback; } },
  set(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch {} }
};

const fmt = (ms) => {
  const s = Math.floor(ms / 1000);
  const h = String(Math.floor(s / 3600)).padStart(2, "0");
  const m = String(Math.floor((s % 3600) / 60)).padStart(2, "0");
  const sec = String(s % 60).padStart(2, "0");
  return `${h}:${m}:${sec}`;
};

const SIZES = [
  { label: "標準", cls: "text-[15px]" },
  { label: "大", cls: "text-[17px]" },
  { label: "特大", cls: "text-[20px]" },
];
const STATUS = [
  { key: 0, label: "未学習", color: "bg-slate-100 text-slate-500" },
  { key: 1, label: "理解した", color: "bg-slate-900 text-white" },
  { key: 2, label: "うろ覚え", color: "bg-slate-300 text-slate-800" },
  { key: 3, label: "要復習", color: "bg-white border border-slate-900 text-slate-900" },
];

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

// ===================== アプリ(1問ずつ表示) =====================
export default function App() {
  const [statuses, setStatuses] = useState(() => store.get("sb-essay-status", {}));
  const [fontSize, setFontSize] = useState(() => store.get("sb-essay-font", 0));
  const [showWatch, setShowWatch] = useState(() => store.get("sb-essay-watch", true));
  const [showAnswer, setShowAnswer] = useState(false);

  const [chap, setChap] = useState(-1);
  const [level, setLevel] = useState(-1); // -1 すべて, 0 基本, 1 発展
  const [statusFilter, setStatusFilter] = useState(-1); // -1 すべて
  const [search, setSearch] = useState("");
  const [randomMode, setRandomMode] = useState(false);
  const [seed, setSeed] = useState(0);
  const [idx, setIdx] = useState(0);

  // ストップウォッチ
  const [watchMs, setWatchMs] = useState(0);
  const [watchRunning, setWatchRunning] = useState(false);
  const tickRef = useRef(null);
  useEffect(() => {
    if (watchRunning) {
      const start = Date.now() - watchMs;
      tickRef.current = setInterval(() => setWatchMs(Date.now() - start), 200);
    } else if (tickRef.current) clearInterval(tickRef.current);
    return () => tickRef.current && clearInterval(tickRef.current);
  }, [watchRunning]);

  useEffect(() => store.set("sb-essay-status", statuses), [statuses]);
  useEffect(() => store.set("sb-essay-font", fontSize), [fontSize]);
  useEffect(() => store.set("sb-essay-watch", showWatch), [showWatch]);

  const setStatus = (id, st) => {
    setStatuses(prev => ({ ...prev, [id]: prev[id] === st ? 0 : st }));
  };

  const filtered = useMemo(() => {
    let list = QUESTIONS.filter(q =>
      (chap === -1 || q.ch === chap) &&
      (level === -1 || q.lv === level) &&
      (statusFilter === -1 || (statuses[q.id] || 0) === statusFilter) &&
      (search === "" || (q.q + q.a + q.e).includes(search))
    );
    if (randomMode) list = shuffle(list);
    return list;
  }, [chap, level, statusFilter, search, randomMode, seed, statuses]);

  // フィルター変更時は先頭の問題へ戻る
  useEffect(() => { setIdx(0); setShowAnswer(false); }, [chap, level, statusFilter, search, randomMode, seed]);

  // 進んだ問題数(理解度をつけた問題)
  const doneCount = useMemo(
    () => QUESTIONS.reduce((n, q) => n + ((statuses[q.id] || 0) > 0 ? 1 : 0), 0),
    [statuses]
  );
  const stats = useMemo(() => {
    const c = [0, 0, 0, 0];
    QUESTIONS.forEach(q => c[statuses[q.id] || 0]++);
    return c;
  }, [statuses]);

  const safeIdx = Math.min(idx, Math.max(filtered.length - 1, 0));
  const current = filtered[safeIdx];

  const goPrev = () => { if (safeIdx > 0) { setIdx(safeIdx - 1); setShowAnswer(false); } };
  const goNext = () => { if (safeIdx < filtered.length - 1) { setIdx(safeIdx + 1); setShowAnswer(false); } };

  // キーボード操作(← →)
  useEffect(() => {
    const onKey = (e) => {
      if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") return;
      if (e.key === "ArrowLeft") goPrev();
      if (e.key === "ArrowRight") goNext();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  const baseText = SIZES[fontSize].cls;
  const chapterCount = (ci) => QUESTIONS.filter(q => q.ch === ci).length;
  const chipOn = "bg-slate-900 text-white border-slate-900";
  const chipOff = "bg-white text-slate-600 border-slate-300 hover:bg-slate-100";

  return (
    <div className={`min-h-screen bg-[#f7f7f7] text-slate-900 ${baseText} leading-relaxed`}>
      {/* ===== ヘッダー ===== */}
      <header className="sticky top-0 z-20 bg-white/95 backdrop-blur border-b border-slate-200 shadow-sm">
        <div className="max-w-3xl mx-auto px-4 py-3">
          <div className="flex flex-wrap items-center gap-2 justify-between">
            <div>
              <h1 className="text-lg sm:text-xl font-bold text-slate-900">セミナー生物 論述問題 一問一答</h1>
              <p className="text-xs text-slate-500">全{QUESTIONS.length}問(No.343〜471)・13単元 · 記述対策</p>
            </div>
            <div className="flex items-center gap-2">
              {/* 進んだ問題数 */}
              <div className="px-3 py-1.5 rounded-full bg-slate-900 text-white text-xs font-semibold">
                進んだ問題数 {doneCount} / {QUESTIONS.length}
              </div>
              {/* ストップウォッチ */}
              <button
                onClick={() => setShowWatch(v => !v)}
                className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors ${showWatch ? "bg-slate-900 text-white border-slate-900" : "bg-white text-slate-500 border-slate-300 hover:bg-slate-100"}`}
              >
                ⏱ {showWatch ? "タイマー表示中" : "タイマー非表示"}
              </button>
              {/* 文字サイズ */}
              <div className="flex rounded-full border border-slate-300 overflow-hidden text-xs">
                {SIZES.map((s, i) => (
                  <button key={s.label} onClick={() => setFontSize(i)}
                    className={`px-2.5 py-1.5 font-semibold ${i === fontSize ? "bg-slate-900 text-white" : "bg-white text-slate-500 hover:bg-slate-100"}`}>
                    {s.label}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* ストップウォッチ本体 */}
          {showWatch && (
            <div className="mt-3 flex flex-wrap items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl px-3 py-2">
              <span className="font-mono text-2xl font-bold text-slate-900 tabular-nums">{fmt(watchMs)}</span>
              <button onClick={() => setWatchRunning(r => !r)}
                className={`px-4 py-1.5 rounded-full text-sm font-semibold text-white ${watchRunning ? "bg-slate-500 hover:bg-slate-600" : "bg-slate-900 hover:bg-slate-800"}`}>
                {watchRunning ? "ストップ" : "スタート"}
              </button>
              <button onClick={() => { setWatchRunning(false); setWatchMs(0); }}
                className="px-4 py-1.5 rounded-full text-sm font-semibold bg-white border border-slate-300 text-slate-700 hover:bg-slate-100">リセット</button>
              <span className="text-xs text-slate-500">📌 記述にかかった時間を測って、時間を意識しながら書く練習をしましょう</span>
            </div>
          )}
        </div>
      </header>

      <main className="max-w-3xl mx-auto px-4 py-5">
        {/* ===== フィルター ===== */}
        <details className="bg-white rounded-2xl border border-slate-200 p-4 shadow-sm mb-5">
          <summary className="cursor-pointer text-sm font-semibold text-slate-700 select-none">▾ 出題範囲・条件の設定(単元 / 基本・発展 / 理解度 / ランダム / 検索)</summary>
          <div className="mt-3 flex flex-wrap gap-1.5">
            <button onClick={() => { setChap(-1); setRandomMode(false); }}
              className={`px-3 py-1.5 rounded-full text-xs font-semibold border ${chap === -1 ? chipOn : chipOff}`}>
              すべて
            </button>
            {CHAPTERS.map((c, i) => (
              <button key={c} onClick={() => { setChap(i); setRandomMode(false); }}
                className={`px-3 py-1.5 rounded-full text-xs font-semibold border ${chap === i ? chipOn : chipOff}`}>
                {c} <span className="opacity-60">({chapterCount(i)})</span>
              </button>
            ))}
          </div>
          <div className="mt-3 flex flex-wrap items-center gap-2">
            {/* 難度 */}
            <div className="flex rounded-lg border border-slate-300 overflow-hidden text-xs">
              {[["すべて", -1], ["基本問題", 0], ["発展問題", 1]].map(([l, v]) => (
                <button key={l} onClick={() => setLevel(v)}
                  className={`px-3 py-1.5 font-semibold ${level === v ? "bg-slate-900 text-white" : "bg-white text-slate-600 hover:bg-slate-100"}`}>{l}</button>
              ))}
            </div>
            {/* 理解度フィルター */}
            <div className="flex rounded-lg border border-slate-300 overflow-hidden text-xs">
              <button onClick={() => setStatusFilter(-1)}
                className={`px-3 py-1.5 font-semibold ${statusFilter === -1 ? "bg-slate-900 text-white" : "bg-white text-slate-600 hover:bg-slate-100"}`}>全状態</button>
              {STATUS.filter(s => s.key > 0).map(s => (
                <button key={s.key} onClick={() => setStatusFilter(s.key)}
                  className={`px-3 py-1.5 font-semibold ${statusFilter === s.key ? "bg-slate-900 text-white" : "bg-white text-slate-600 hover:bg-slate-100"}`}>
                  {s.label}{stats[s.key]}
                </button>
              ))}
            </div>
            {/* ランダム */}
            <button onClick={() => { setRandomMode(v => !v); setSeed(s => s + 1); }}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold border ${randomMode ? "bg-slate-900 text-white border-slate-900" : chipOff}`}>
              🎲 ランダム出題{randomMode ? " ON" : ""}
            </button>
            {/* 検索 */}
            <input value={search} onChange={e => setSearch(e.target.value)} placeholder="🔍 キーワード検索(例:光合成)"
              className="flex-1 min-w-[160px] px-3 py-1.5 rounded-lg border border-slate-300 text-xs focus:outline-none focus:ring-2 focus:ring-slate-400" />
            {(search || level !== -1 || statusFilter !== -1 || chap !== -1) && (
              <button onClick={() => { setSearch(""); setLevel(-1); setStatusFilter(-1); setChap(-1); setRandomMode(false); }} className="text-xs text-slate-400 underline">条件クリア</button>
            )}
          </div>
        </details>

        {/* ===== 1問ずつ表示 ===== */}
        {filtered.length === 0 || !current ? (
          <p className="text-center text-slate-400 py-12">条件に合う問題はありません。</p>
        ) : (
          <>
            {/* 位置表示 */}
            <div className="flex items-center justify-between mb-3 text-xs text-slate-500">
              <span>第 <b className="text-slate-900">{safeIdx + 1}</b> 問目 / 全{filtered.length}問{randomMode && "(ランダム)"}</span>
              <span className="hidden sm:inline">⌨️ ← / → キーでも移動できます</span>
            </div>

            <article className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
              {/* 問題ヘッダー */}
              <div className="px-5 pt-4 pb-2 flex flex-wrap items-center gap-2 border-b border-slate-100">
                <span className="font-mono font-bold text-slate-900 text-lg">No.{current.id}</span>
                <span className="text-[11px] px-2 py-0.5 rounded-full bg-slate-100 text-slate-700 font-semibold">{CHAPTERS[current.ch]}</span>
                <span className={`text-[11px] px-2 py-0.5 rounded-full font-semibold ${current.lv === 0 ? "bg-slate-100 text-slate-600" : "bg-slate-900 text-white"}`}>{current.lv === 0 ? "基本" : "発展"}</span>
                {current.s && <span className="text-[11px] px-2 py-0.5 rounded-full bg-slate-100 text-slate-500 font-semibold">出典: {current.s}</span>}
                <span className={`text-[11px] px-2 py-0.5 rounded-full font-semibold ${STATUS[statuses[current.id] || 0].color}`}>{STATUS[statuses[current.id] || 0].label}</span>
              </div>
              {/* 問題文 */}
              <div className="px-5 py-5">
                <p className="whitespace-pre-wrap">{current.q}</p>
                {current.k.length > 0 && (
                  <div className="mt-3 flex flex-wrap gap-1.5">
                    {current.k.map(kw => <span key={kw} className="text-xs px-2 py-0.5 rounded-full bg-slate-100 border border-slate-300 text-slate-700">【{kw}】</span>)}
                  </div>
                )}
              </div>
              {/* 展開ボタン */}
              <button onClick={() => setShowAnswer(v => !v)}
                className={`w-full px-5 py-3 text-sm font-semibold border-t transition-colors ${showAnswer ? "bg-slate-900 text-white border-slate-900" : "bg-slate-50 text-slate-700 border-slate-100 hover:bg-slate-100"}`}>
                {showAnswer ? "解答・解説を閉じる ▲" : "解答・解説を表示 ▼"}
              </button>
              {/* 解答・解説 */}
              {showAnswer && (
                <div className="px-5 py-4 bg-[#fbfbfb] border-t border-slate-100 space-y-3">
                  <div>
                    <h3 className="text-xs font-bold text-slate-500 mb-1">✍️ 模範解答</h3>
                    <p className="bg-white rounded-xl border border-slate-200 p-3 whitespace-pre-wrap">{current.a}</p>
                  </div>
                  <div>
                    <h3 className="text-xs font-bold text-slate-500 mb-1">✅ Check point</h3>
                    <p className="bg-white rounded-xl border border-slate-200 p-3">{current.c}</p>
                  </div>
                  <div>
                    <h3 className="text-xs font-bold text-slate-500 mb-1">💡 解法のポイント</h3>
                    <p className="bg-white rounded-xl border border-slate-200 p-3 whitespace-pre-wrap text-slate-700">{current.e}</p>
                  </div>
                  {/* 理解度 */}
                  <div className="flex flex-wrap items-center gap-2 pt-1">
                    <span className="text-xs font-semibold text-slate-500">理解度チェック:</span>
                    {STATUS.filter(s => s.key > 0).map(s => (
                      <button key={s.key} onClick={() => setStatus(current.id, s.key)}
                        className={`text-xs px-3 py-1.5 rounded-full font-semibold border transition-all ${((statuses[current.id] || 0) === s.key) ? (s.color + " ring-2 ring-offset-1 ring-slate-300") : "bg-white border-slate-300 text-slate-500 hover:bg-slate-100"}`}>
                        {((statuses[current.id] || 0) === s.key) ? "✓ " : ""}{s.label}
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </article>

            {/* 前後ナビ */}
            <div className="mt-5 flex items-center justify-between gap-3">
              <button onClick={goPrev} disabled={safeIdx === 0}
                className="px-5 py-2.5 rounded-full text-sm font-semibold bg-white border border-slate-300 text-slate-700 hover:bg-slate-100 disabled:opacity-30 disabled:cursor-not-allowed">
                ← 前の問題
              </button>
              <button onClick={() => { setIdx(0); setShowAnswer(false); }}
                className="px-4 py-2.5 rounded-full text-xs font-semibold bg-white border border-slate-300 text-slate-500 hover:bg-slate-100">
                最初に戻る
              </button>
              <button onClick={goNext} disabled={safeIdx === filtered.length - 1}
                className="px-6 py-2.5 rounded-full text-sm font-semibold bg-slate-900 text-white hover:bg-slate-800 disabled:opacity-30 disabled:cursor-not-allowed">
                次の問題 →
              </button>
            </div>
          </>
        )}

        <footer className="mt-8 mb-4 text-center text-xs text-slate-400">
          <p>学習状態・文字サイズ・タイマー設定は自動保存されます(同じ端末・ブラウザで有効)</p>
          <p className="mt-1">セミナー生物「論述問題」(No.343〜471)にもとづく学習用アプリ</p>
        </footer>
      </main>
    </div>
  );
}
